// FileseqWalk walks n's subtree depth first, as ANTLR's ParseTreeWalker does:
// at each node EnterEveryRule and the node's Enter method, then its children
// in order (VisitTerminal for a token, VisitErrorNode for an error token),
// then its Exit method and ExitEveryRule. It keeps its own stack, so a deep
// tree cannot overflow Go's.
func FileseqWalk(n FileseqNodeRef, l FileseqListener) {
	if !n.Ok() {
		return
	}
	type frame struct {
		n    FileseqNodeRef
		next int
	}
	stack := []frame{{n, -1}}
	for len(stack) > 0 {
		f := &stack[len(stack)-1]
		if f.next < 0 {
			l.EnterEveryRule(f.n)
			fileseqGalopEnter(l, f.n)
			f.next = 0
		}
		if f.next < f.n.ChildCount() {
			c := f.n.Child(f.next)
			f.next++
			switch {
			case c.IsError():
				l.VisitErrorNode(c.Terminal())
			case c.IsToken():
				l.VisitTerminal(c.Terminal())
			default:
				stack = append(stack, frame{c.Node(), -1})
			}
			continue
		}
		fileseqGalopExit(l, f.n)
		l.ExitEveryRule(f.n)
		stack = stack[:len(stack)-1]
	}
}

// fileseqGalopEnter calls l's Enter method for n's kind.
func fileseqGalopEnter(l FileseqListener, n FileseqNodeRef) {
	switch n.Kind() {
	case FileseqKIND_input:
		l.EnterInput(InputNode{n})
	case FileseqKIND_sequence:
		l.EnterSequence(SequenceNode{n})
	case FileseqKIND_patternOnly:
		l.EnterPatternOnly(PatternOnlyNode{n})
	case FileseqKIND_singleFrame:
		l.EnterSingleFrame(SingleFrameNode{n})
	case FileseqKIND_plainFile:
		l.EnterPlainFile(PlainFileNode{n})
	case FileseqKIND_directory:
		l.EnterDirectory(DirectoryNode{n})
	case FileseqKIND_basenameChar:
		l.EnterBasenameChar(BasenameCharNode{n})
	case FileseqKIND_plainBasenameChar:
		l.EnterPlainBasenameChar(PlainBasenameCharNode{n})
	case FileseqKIND_dirSegment:
		l.EnterDirSegment(DirSegmentNode{n})
	case FileseqKIND_basename:
		l.EnterBasename(BasenameNode{n})
	case FileseqKIND_plainBasename:
		l.EnterPlainBasename(PlainBasenameNode{n})
	case FileseqKIND_frameRange:
		l.EnterFrameRange(FrameRangeNode{n})
	case FileseqKIND_frameNum:
		l.EnterFrameNum(FrameNumNode{n})
	case FileseqKIND_padding:
		l.EnterPadding(PaddingNode{n})
	case FileseqKIND_extension:
		l.EnterExtension(ExtensionNode{n})
	}
}

// fileseqGalopExit calls l's Exit method for n's kind.
func fileseqGalopExit(l FileseqListener, n FileseqNodeRef) {
	switch n.Kind() {
	case FileseqKIND_input:
		l.ExitInput(InputNode{n})
	case FileseqKIND_sequence:
		l.ExitSequence(SequenceNode{n})
	case FileseqKIND_patternOnly:
		l.ExitPatternOnly(PatternOnlyNode{n})
	case FileseqKIND_singleFrame:
		l.ExitSingleFrame(SingleFrameNode{n})
	case FileseqKIND_plainFile:
		l.ExitPlainFile(PlainFileNode{n})
	case FileseqKIND_directory:
		l.ExitDirectory(DirectoryNode{n})
	case FileseqKIND_basenameChar:
		l.ExitBasenameChar(BasenameCharNode{n})
	case FileseqKIND_plainBasenameChar:
		l.ExitPlainBasenameChar(PlainBasenameCharNode{n})
	case FileseqKIND_dirSegment:
		l.ExitDirSegment(DirSegmentNode{n})
	case FileseqKIND_basename:
		l.ExitBasename(BasenameNode{n})
	case FileseqKIND_plainBasename:
		l.ExitPlainBasename(PlainBasenameNode{n})
	case FileseqKIND_frameRange:
		l.ExitFrameRange(FrameRangeNode{n})
	case FileseqKIND_frameNum:
		l.ExitFrameNum(FrameNumNode{n})
	case FileseqKIND_padding:
		l.ExitPadding(PaddingNode{n})
	case FileseqKIND_extension:
		l.ExitExtension(ExtensionNode{n})
	}
}

// ParseInput parses the tokens of ts as input, from the first token, and
// returns the tree's root. On a syntax error it returns the error and no tree.
// The parse stops after the input input matches; Tree().Next is the index of
// the token after it.
func ParseInput(ts *FileseqTokens) (InputNode, error) {
	t, root, err := fileseqGalopRun(ts, (*fileseqGalopParser).ruleInput, 0, true)
	if err != nil {
		return InputNode{}, err
	}
	return InputNode{FileseqNodeRef{t, root}}, nil
}

// ParseInputWithRecovery is ParseInput that recovers from syntax errors as
// ANTLR does, returning a tree and every error (see FileseqParseWithRecovery).
func ParseInputWithRecovery(ts *FileseqTokens) (InputNode, []FileseqParseError) {
	root, errs := FileseqParseWithRecovery(ts, 0)
	return InputNode{root}, errs
}

// ParseSequence parses the tokens of ts as sequence, from the first token, and
// returns the tree's root. On a syntax error it returns the error and no tree.
// The parse stops after the input sequence matches; Tree().Next is the index of
// the token after it.
func ParseSequence(ts *FileseqTokens) (SequenceNode, error) {
	t, root, err := fileseqGalopRun(ts, (*fileseqGalopParser).ruleSequence, 2, false)
	if err != nil {
		return SequenceNode{}, err
	}
	return SequenceNode{FileseqNodeRef{t, root}}, nil
}

// ParseSequenceWithRecovery is ParseSequence that recovers from syntax errors as
// ANTLR does, returning a tree and every error (see FileseqParseWithRecovery).
func ParseSequenceWithRecovery(ts *FileseqTokens) (SequenceNode, []FileseqParseError) {
	root, errs := FileseqParseWithRecovery(ts, 1)
	return SequenceNode{root}, errs
}

// ParsePatternOnly parses the tokens of ts as patternOnly, from the first token, and
// returns the tree's root. On a syntax error it returns the error and no tree.
// The parse stops after the input patternOnly matches; Tree().Next is the index of
// the token after it.
func ParsePatternOnly(ts *FileseqTokens) (PatternOnlyNode, error) {
	t, root, err := fileseqGalopRun(ts, (*fileseqGalopParser).rulePatternOnly, 4, false)
	if err != nil {
		return PatternOnlyNode{}, err
	}
	return PatternOnlyNode{FileseqNodeRef{t, root}}, nil
}

// ParsePatternOnlyWithRecovery is ParsePatternOnly that recovers from syntax errors as
// ANTLR does, returning a tree and every error (see FileseqParseWithRecovery).
func ParsePatternOnlyWithRecovery(ts *FileseqTokens) (PatternOnlyNode, []FileseqParseError) {
	root, errs := FileseqParseWithRecovery(ts, 2)
	return PatternOnlyNode{root}, errs
}

// ParseSingleFrame parses the tokens of ts as singleFrame, from the first token, and
// returns the tree's root. On a syntax error it returns the error and no tree.
// The parse stops after the input singleFrame matches; Tree().Next is the index of
