// fileseqGalopEmptyReturn is the return state that marks the end of the outermost context.
const fileseqGalopEmptyReturn = int32(0x7fffffff)

// fileseqGalopCtxPool holds hash-consed prediction contexts. Context 0 is EMPTY; every
// other context is a singleton (one return state and parent) or an array
// (return states in ascending order, with parents). A parent of -1 is nil.
type fileseqGalopCtxPool struct {
	wildcard bool
	kind     []uint8
	start    []int32
	length   []int32
	rets     []int32
	parents  []int32
	next     []int32
	heads    fileseqGalopMap
	singles  fileseqGalopMap
	merges   fileseqGalopMap
}

const (
	fileseqGalopCtxEmpty     = 0
	fileseqGalopCtxSingleton = 1
	fileseqGalopCtxArray     = 2
)

func (cp *fileseqGalopCtxPool) reset(wildcard bool) {
	cp.wildcard = wildcard
	cp.kind = append(cp.kind[:0], fileseqGalopCtxEmpty)
	cp.start = append(cp.start[:0], 0)
	cp.length = append(cp.length[:0], 1)
	cp.rets = append(cp.rets[:0], fileseqGalopEmptyReturn)
	cp.parents = append(cp.parents[:0], -1)
	cp.next = append(cp.next[:0], -1)
	cp.heads.reset()
	cp.singles.reset()
	cp.merges.reset()
}

// intern returns the id of the context (kind, rets, parents), adding it if new.
// Contexts are found through a hash of their contents and a chain of the ids
// that share it. Singletons are interned by singleton instead.
func (cp *fileseqGalopCtxPool) intern(kind uint8, rets, parents []int32) int32 {
	h := uint64(kind) + 0x9e3779b97f4a7c15
	for i := range rets {
		h = fileseqGalopMix(h ^ (uint64(uint32(rets[i]))<<32 | uint64(uint32(parents[i]))))
	}
	head, found := cp.heads.get(h)
	if found {
		for id := head; id >= 0; id = cp.next[id] {
			if cp.kind[id] != kind || int(cp.length[id]) != len(rets) {
				continue
			}
			s, same := cp.start[id], true
			for i := range rets {
				if cp.rets[s+int32(i)] != rets[i] || cp.parents[s+int32(i)] != parents[i] {
					same = false
					break
				}
			}
			if same {
				return id
			}
		}
	} else {
		head = -1
	}
	id := int32(len(cp.kind))
	cp.kind = append(cp.kind, kind)
	cp.start = append(cp.start, int32(len(cp.rets)))
	cp.length = append(cp.length, int32(len(rets)))
	cp.rets = append(cp.rets, rets...)
	cp.parents = append(cp.parents, parents...)
	cp.next = append(cp.next, head)
	cp.heads.set(h, id)
	return id
}

// singleton is ANTLR's SingletonBasePredictionContextCreate. Closure creates
// one at every rule call, so singletons skip the hash chains of intern: their
// return state and parent are the whole key.
func (cp *fileseqGalopCtxPool) singleton(parent, ret int32) int32 {
	if ret == fileseqGalopEmptyReturn && parent < 0 {
		return 0
	}
	k := uint64(uint32(ret))<<32 | uint64(uint32(parent))
	if id, ok := cp.singles.get(k); ok {
		return id
	}
	id := int32(len(cp.kind))
	cp.kind = append(cp.kind, fileseqGalopCtxSingleton)
	cp.start = append(cp.start, int32(len(cp.rets)))
	cp.length = append(cp.length, 1)
	cp.rets = append(cp.rets, ret)
	cp.parents = append(cp.parents, parent)
	cp.next = append(cp.next, -1)
	cp.singles.set(k, id)
	return id
}

func (cp *fileseqGalopCtxPool) isEmpty(c int32) bool {
	switch cp.kind[c] {
	case fileseqGalopCtxEmpty:
		return true
	case fileseqGalopCtxArray:
		return cp.length[c] > 0 && cp.rets[cp.start[c]] == fileseqGalopEmptyReturn
	}
	return false
}

// toArray is ANTLR's convertToArray: EMPTY becomes an array with no entries.
func (cp *fileseqGalopCtxPool) toArray(c int32) int32 {
	switch cp.kind[c] {
	case fileseqGalopCtxEmpty:
		return cp.intern(fileseqGalopCtxArray, nil, nil)
	case fileseqGalopCtxSingleton:
		s := cp.start[c]
		one := [2]int32{cp.rets[s], cp.parents[s]}
		return cp.intern(fileseqGalopCtxArray, one[0:1], one[1:2])
	}
	return c
}

func fileseqGalopMergeKey(a, b int32) uint64 { return uint64(uint32(a))<<32 | uint64(uint32(b)) }

func (cp *fileseqGalopCtxPool) cached(a, b int32) (int32, bool) {
	if r, ok := cp.merges.get(fileseqGalopMergeKey(a, b)); ok {
		return r, true
	}
	return cp.merges.get(fileseqGalopMergeKey(b, a))
}

// merge is ANTLR's merge(a, b, rootIsWildcard, mergeCache).
func (cp *fileseqGalopCtxPool) merge(a, b int32) int32 {
	if a == b {
		return a
	}
	if cp.kind[a] == fileseqGalopCtxSingleton && cp.kind[b] == fileseqGalopCtxSingleton {
		return cp.mergeSingletons(a, b)
	}
	if cp.wildcard {
		if cp.isEmpty(a) {
			return a
		}
		if cp.isEmpty(b) {
			return b
		}
	}
	return cp.mergeArrays(cp.toArray(a), cp.toArray(b))
}

func (cp *fileseqGalopCtxPool) mergeSingletons(a, b int32) int32 {
	if r, ok := cp.cached(a, b); ok {
		return r
	}
	ar, ap := cp.rets[cp.start[a]], cp.parents[cp.start[a]]
	br, bp := cp.rets[cp.start[b]], cp.parents[cp.start[b]]
	var r int32
	if ar == br {
		parent := cp.merge(ap, bp)
		if parent == ap {
			return a
		}
		if parent == bp {
			return b
		}
		r = cp.singleton(parent, ar)
	} else if ap >= 0 && ap == bp {
		lo, hi := min(ar, br), max(ar, br)
		r = cp.intern(fileseqGalopCtxArray, []int32{lo, hi}, []int32{ap, ap})
	} else if ar < br {
		r = cp.intern(fileseqGalopCtxArray, []int32{ar, br}, []int32{ap, bp})
	} else {
		r = cp.intern(fileseqGalopCtxArray, []int32{br, ar}, []int32{bp, ap})
	}
	cp.merges.set(fileseqGalopMergeKey(a, b), r)
	return r
}

func (cp *fileseqGalopCtxPool) mergeArrays(a, b int32) int32 {
	if r, ok := cp.cached(a, b); ok {
		return r
	}
	as, al := cp.start[a], cp.length[a]
	bs, bl := cp.start[b], cp.length[b]
	rets := make([]int32, 0, al+bl)
	parents := make([]int32, 0, al+bl)
	i, j := int32(0), int32(0)
	for i < al && j < bl {
		ar, ap := cp.rets[as+i], cp.parents[as+i]
		br, bp := cp.rets[bs+j], cp.parents[bs+j]
		switch {
		case ar == br:
			bothDollars := ar == fileseqGalopEmptyReturn && ap < 0 && bp < 0
			if bothDollars || (ap >= 0 && bp >= 0 && ap == bp) {
				parents = append(parents, ap)
			} else {
				parents = append(parents, cp.merge(ap, bp))
				// The merge may have grown the pool; re-read the bases.
				as, bs = cp.start[a], cp.start[b]
			}
			rets = append(rets, ar)
			i++
			j++
		case ar < br:
			rets, parents = append(rets, ar), append(parents, ap)
			i++
		default:
			rets, parents = append(rets, br), append(parents, bp)
			j++
		}
	}
	for ; i < al; i++ {
		rets, parents = append(rets, cp.rets[as+i]), append(parents, cp.parents[as+i])
	}
	for ; j < bl; j++ {
		rets, parents = append(rets, cp.rets[bs+j]), append(parents, cp.parents[bs+j])
	}
	var r int32
	if int32(len(rets)) < al+bl && len(rets) == 1 {
		r = cp.singleton(parents[0], rets[0])
	} else {
		r = cp.intern(fileseqGalopCtxArray, rets, parents)
	}
	cp.merges.set(fileseqGalopMergeKey(a, b), r)
	return r
}

// fileseqGalopConfig is an ATN configuration: a state, the alternative it predicts and
// its context (an id in the predictor's pool).
type fileseqGalopConfig struct {
	state int32
	alt   int32
	ctx   int32
}

func (c fileseqGalopConfig) key() uint64 {
	return uint64(uint32(c.ctx))<<32 | uint64(uint32(c.state))<<12 | uint64(uint32(c.alt)&0xfff)
}

// fileseqGalopMap maps uint64 keys to int32 values: open addressing, cleared in O(1)
// by bumping the generation. A slot holds its key, value and generation
// together, so a probe reads one cache line.
type fileseqGalopMap struct {
	slots []fileseqGalopSlot
	gen   uint32
	n     int
}

type fileseqGalopSlot struct {
	key uint64
	val int32
	gen uint32
}

func (m *fileseqGalopMap) reset() {
	m.gen++
	m.n = 0
	if m.slots == nil || m.gen == 0 {
		m.slots = make([]fileseqGalopSlot, 64)
		m.gen = 1
	}
}

func fileseqGalopMix(k uint64) uint64 {
	k ^= k >> 33
	k *= 0xff51afd7ed558ccd
	k ^= k >> 33
	return k
}

// put stores v for k unless k is present; it returns the stored value and
// whether k was new.
func (m *fileseqGalopMap) put(k uint64, v int32) (int32, bool) {
	if 2*(m.n+1) > len(m.slots) {
		m.grow()
	}
	mask := uint64(len(m.slots) - 1)
	for i := fileseqGalopMix(k) & mask; ; i = (i + 1) & mask {
		s := &m.slots[i]
		if s.gen != m.gen {
			*s = fileseqGalopSlot{k, v, m.gen}
			m.n++
			return v, true
		}
		if s.key == k {
			return s.val, false
		}
	}
}

// get returns the value stored for k.
func (m *fileseqGalopMap) get(k uint64) (int32, bool) {
	if m.n == 0 {
		return 0, false
	}
	mask := uint64(len(m.slots) - 1)
	for i := fileseqGalopMix(k) & mask; ; i = (i + 1) & mask {
		s := &m.slots[i]
		if s.gen != m.gen {
			return 0, false
		}
		if s.key == k {
			return s.val, true
		}
	}
}

// set stores v for k, replacing any earlier value.
func (m *fileseqGalopMap) set(k uint64, v int32) {
	if 2*(m.n+1) > len(m.slots) {
		m.grow()
	}
	mask := uint64(len(m.slots) - 1)
	for i := fileseqGalopMix(k) & mask; ; i = (i + 1) & mask {
		s := &m.slots[i]
		if s.gen != m.gen {
			*s = fileseqGalopSlot{k, v, m.gen}
			m.n++
			return
		}
		if s.key == k {
			s.val = v
			return
		}
	}
}

func (m *fileseqGalopMap) grow() {
	old, gen := m.slots, m.gen
	m.slots = make([]fileseqGalopSlot, 2*len(old))
	m.gen = 1
	m.n = 0
	for _, s := range old {
		if s.gen == gen {
			m.put(s.key, s.val)
		}
	}
}

// fileseqGalopConfigSet is ANTLR's ATNConfigSet: one configuration per (state, alt),
// whose context is the merge of every context added for it.
type fileseqGalopConfigSet struct {
	list []fileseqGalopConfig
	at   fileseqGalopMap
}

func (s *fileseqGalopConfigSet) add(c fileseqGalopConfig, cp *fileseqGalopCtxPool) {
	k := uint64(uint32(c.state))<<32 | uint64(uint32(c.alt))
	if i, isNew := s.at.put(k, int32(len(s.list))); !isNew {
		s.list[i].ctx = cp.merge(s.list[i].ctx, c.ctx)
		return
	}
	s.list = append(s.list, c)
}

func (s *fileseqGalopConfigSet) reset() {
	s.list = s.list[:0]
	s.at.reset()
}

// fileseqGalopPredictor holds the scratch state of runtime prediction.
type fileseqGalopPredictor struct {
	full    bool
	pool    fileseqGalopCtxPool
	busy    fileseqGalopMap
	sets    [3]fileseqGalopConfigSet
	skipped []fileseqGalopConfig
	sorted  []fileseqGalopConfig
	multi   bool
	// Scratch for subsets.
	groups     fileseqGalopMap
	states     fileseqGalopMap
	groupMin   []int32
	stateAlt   []int32
	stateMulti []bool
	// prec is the precedence the decision's rule invocation was called with,
	// and collect says a start state is being computed (see closure).
	prec    int32
	collect bool
	// While the start state of a left-recursive rule's loop entry is
	// computed, filter is set and rule is the decision's rule; suppress
	// says the closure being followed left an outermost call of that rule,
	// and suppressed collects the (state, alt) keys of the configurations
	// it added (ANTLR's precedenceFilterSuppressed). alt1 is scratch for
	// precedenceFilter.
	filter     bool
	rule       int32
	suppress   bool
	suppressed fileseqGalopMap
	alt1       fileseqGalopMap
}

// busyKey is c's key, met at depth, in the closure's busy set. ANTLR's
// configurations differ in their precedenceFilterSuppressed flag too
// (bit 63). And what c reaches depends on whether precedence predicates
// apply to it (bit 61; see passes): ANTLR's closure marks no state busy on
// an epsilon path, so a state a filtered path met in the decision's own
// rule invocation is followed again when the closure returns to it from
// outside, where the predicates are epsilon. Bit 62 marks loopEntry's keys;
// context ids stay below 1<<29.
func (pr *fileseqGalopPredictor) busyKey(c fileseqGalopConfig, depth int32) uint64 {
	key := c.key()
	if pr.suppress {
		key |= 1 << 63
	}
	if pr.collect && depth == 0 {
		key |= 1 << 61
	}
	return key
}

// added records, while a start state is filtered, that c was added with
// the current suppress flag.
func (pr *fileseqGalopPredictor) added(out *fileseqGalopConfigSet, c fileseqGalopConfig) {
	out.add(c, &pr.pool)
	if pr.suppress {
		pr.suppressed.put(uint64(uint32(c.state))<<32|uint64(uint32(c.alt)), 0)
	}
}

// matches reports whether consuming transition i accepts token type t.
func fileseqGalopMatches(i int32, t int32) bool {
	switch fileseqGalopTransKind[i] {
	case fileseqGalopKindAtom:
		return fileseqGalopTransArg[i] == t
	case fileseqGalopKindSet:
		return fileseqGalopInSet(fileseqGalopSets[fileseqGalopTransArg[i]], t)
	}
	return false
}

// fileseqGalopInSet reports whether token type t is in set, a list of ranges.
func fileseqGalopInSet(set []int32, t int32) bool {
	lo, hi := 0, len(set)/2-1
	for lo <= hi {
		mid := (lo + hi) / 2
		if t < set[2*mid] {
			hi = mid - 1
		} else if t > set[2*mid+1] {
			lo = mid + 1
		} else {
			return true
		}
	}
	return false
}

// closure adds c and every configuration reachable from it without consuming
// a token to out (ANTLR's closureCheckingStopState and closureWork).
//
// Within a rule, what a state reaches without consuming is the same in every
// context, so it comes from the precomputed fileseqGalopClos tables; only rule calls,
// rule ends and precedence predicates are handled here. After EOF,
// transitions that match EOF also count as epsilon, which the tables do not
// cover, so that case walks the ATN.
//
// depth is ANTLR's closure depth: rules entered since the decision, less
// rules left (it stays negative once the decision's rule is left). While a
// start state is computed (pr.collect), a precedence predicate met at depth 0,
// in the decision's own rule invocation, passes when its level is at least
// pr.prec, the precedence that invocation was called with, and the path
// stops otherwise; anywhere else it is epsilon, as in ANTLR's prediction.
func (pr *fileseqGalopPredictor) closure(c fileseqGalopConfig, out *fileseqGalopConfigSet, eofAsEpsilon bool, depth int32) {
	if _, isNew := pr.busy.put(pr.busyKey(c, depth), 0); !isNew {
		return
	}
	if fileseqGalopStateIsStop[c.state] {
		pr.ruleEnd(c, out, eofAsEpsilon, depth)
		return
	}
	if eofAsEpsilon {
		pr.walk(c, out, depth)
		return
	}
	cp := &pr.pool
	for i := fileseqGalopClosStart[c.state]; i < fileseqGalopClosStart[c.state+1]; i++ {
		s := fileseqGalopClosState[i]
		switch fileseqGalopClosKind[i] {
		case 0:
			pr.added(out, fileseqGalopConfig{s, c.alt, c.ctx})
		case 1:
			pr.closure(fileseqGalopConfig{s, c.alt, cp.singleton(c.ctx, fileseqGalopClosArg[i])}, out, false, fileseqGalopDeeper(depth))
		case 3:
			if !pr.passes(fileseqGalopClosArg[i], depth) {
				continue
			}
			pr.closure(fileseqGalopConfig{s, c.alt, c.ctx}, out, false, depth)
		case 4:
			pr.loopEntry(fileseqGalopConfig{s, c.alt, c.ctx}, out, depth)
		default:
			pr.closure(fileseqGalopConfig{s, c.alt, c.ctx}, out, false, depth)
		}
	}
}

// loopEntry continues c, at the loop entry of a left-recursive rule, into
// the loop and out of it, but not into the loop where canDrop says the
// invocation returned to goes on in it the same way.
func (pr *fileseqGalopPredictor) loopEntry(c fileseqGalopConfig, out *fileseqGalopConfigSet, depth int32) {
	if _, isNew := pr.busy.put(pr.busyKey(c, depth)|1<<62, 0); !isNew {
		return
	}
	for i := fileseqGalopTransStart[c.state]; i < fileseqGalopTransStart[c.state+1]; i++ {
		if i == fileseqGalopTransStart[c.state] && pr.canDrop(c) {
			continue
		}
		pr.closure(fileseqGalopConfig{fileseqGalopTransTarget[i], c.alt, c.ctx}, out, false, depth)
	}
}

// canDrop is ANTLR's canDropLoopEntryEdgeInLeftRecursiveRule: c is at the
// loop entry of a left-recursive rule, and every return state of its context
// leads straight back to that entry (fileseqGalopStateLoopReturn), so the invocation
// returned to goes on in the loop and c need not enter it.
func (pr *fileseqGalopPredictor) canDrop(c fileseqGalopConfig) bool {
	return fileseqGalopStatePrecLoop[c.state] && pr.pool.canDrop(c.state, c.ctx)
}

// canDrop is canDrop for a configuration at state with context ctx in cp.
func (cp *fileseqGalopCtxPool) canDrop(state, ctx int32) bool {
	if cp.isEmpty(ctx) {
		return false
	}
	from, n := cp.start[ctx], cp.length[ctx]
	if cp.rets[from+n-1] == fileseqGalopEmptyReturn {
		return false
	}
	for i := int32(0); i < n; i++ {
		if fileseqGalopStateLoopReturn[cp.rets[from+i]] != state {
			return false
		}
	}
	return true
}

// fileseqGalopDeeper is the depth inside a rule called at depth: one more, unless the
// decision's rule was already left.
func fileseqGalopDeeper(depth int32) int32 {
	if depth >= 0 {
		return depth + 1
	}
	return depth
}

// passes says whether a precedence predicate of level, met at depth, lets a
// closure go on (see closure).
func (pr *fileseqGalopPredictor) passes(level int32, depth int32) bool {
	return !pr.collect || depth != 0 || level >= pr.prec
}

// walk is closure over the ATN transitions themselves, for after EOF.
func (pr *fileseqGalopPredictor) walk(c fileseqGalopConfig, out *fileseqGalopConfigSet, depth int32) {
	cp := &pr.pool
	if !fileseqGalopStateEpsOnly[c.state] {
		pr.added(out, c)
	}
	for i := fileseqGalopTransStart[c.state]; i < fileseqGalopTransStart[c.state+1]; i++ {
		if i == fileseqGalopTransStart[c.state] && pr.canDrop(c) {
			continue
		}
		switch fileseqGalopTransKind[i] {
		case fileseqGalopKindEpsilon:
			pr.closure(fileseqGalopConfig{fileseqGalopTransTarget[i], c.alt, c.ctx}, out, true, depth)
		case fileseqGalopKindPrec:
			if pr.passes(fileseqGalopTransArg[i], depth) {
				pr.closure(fileseqGalopConfig{fileseqGalopTransTarget[i], c.alt, c.ctx}, out, true, depth)
			}
		case fileseqGalopKindRule:
			pr.closure(fileseqGalopConfig{fileseqGalopTransTarget[i], c.alt, cp.singleton(c.ctx, fileseqGalopTransArg[i])}, out, true, fileseqGalopDeeper(depth))
		default:
			if fileseqGalopMatches(i, -1) {
				pr.closure(fileseqGalopConfig{fileseqGalopTransTarget[i], c.alt, c.ctx}, out, true, depth)
			}
		}
	}
}

// ruleEnd continues a configuration at a rule's end: back to each return state
// of its context, or, with the context exhausted, at the end of the start rule
// (LL) or after every call of the rule (SLL).
func (pr *fileseqGalopPredictor) ruleEnd(c fileseqGalopConfig, out *fileseqGalopConfigSet, eofAsEpsilon bool, depth int32) {
	cp := &pr.pool
	{
		if !cp.isEmpty(c.ctx) {
			for i := int32(0); i < cp.length[c.ctx]; i++ {
				ret, parent := cp.rets[cp.start[c.ctx]+i], cp.parents[cp.start[c.ctx]+i]
				if ret == fileseqGalopEmptyReturn {
					if pr.full {
						out.add(fileseqGalopConfig{c.state, c.alt, 0}, cp)
					} else {
						pr.follow(c, out, eofAsEpsilon, depth-1)
					}
					continue
				}
				pr.closure(fileseqGalopConfig{ret, c.alt, parent}, out, eofAsEpsilon, depth-1)
			}
			return
		}
		if pr.full {
			// End of the start rule in full context.
			out.add(c, cp)
			return
		}
		pr.follow(c, out, eofAsEpsilon, depth-1)
	}
}

// follow continues a configuration at a rule's end after every call of the
// rule (ANTLR's rule-stop follow links, used when the caller is unknown). A
// rule nobody calls keeps the configuration at its end.
func (pr *fileseqGalopPredictor) follow(c fileseqGalopConfig, out *fileseqGalopConfigSet, eofAsEpsilon bool, depth int32) {
	rule := fileseqGalopStateRule[c.state]
	if fileseqGalopFollowStart[rule] == fileseqGalopFollowStart[rule+1] {
		pr.added(out, c)
		return
	}
	for i := fileseqGalopFollowStart[rule]; i < fileseqGalopFollowStart[rule+1]; i++ {
		if pr.filter && rule == pr.rule && fileseqGalopFollowOuter[i] && !pr.suppress {
			// Past an outermost call of the decision's rule, the precedence
			// filter spares what the closure reaches.
			pr.suppress = true
			pr.closure(fileseqGalopConfig{fileseqGalopFollowState[i], c.alt, c.ctx}, out, eofAsEpsilon, depth)
			pr.suppress = false
			continue
		}
		pr.closure(fileseqGalopConfig{fileseqGalopFollowState[i], c.alt, c.ctx}, out, eofAsEpsilon, depth)
	}
}

func fileseqGalopUniqueAlt(list []fileseqGalopConfig) int32 {
	alt := int32(0)
	for _, c := range list {
		if alt == 0 {
			alt = c.alt
		} else if c.alt != alt {
			return 0
		}
	}
	return alt
}

// reach computes the configurations reachable from closure by consuming t
// (ANTLR's computeReachSet). With group set, t is an opening bracket and the
// whole bracketed group is consumed: a configuration moves to the states after
// the matching closer. The result is in out; a non-zero return is an
// alternative decided early.
func (pr *fileseqGalopPredictor) reach(closure *fileseqGalopConfigSet, t int32, group bool, intermediate, out *fileseqGalopConfigSet) int32 {
	cp := &pr.pool
	intermediate.reset()
	pr.skipped = pr.skipped[:0]
	for _, c := range closure.list {
		if fileseqGalopStateIsStop[c.state] {
			if pr.full || t == -1 {
				pr.skipped = append(pr.skipped, c)
			}
			continue
		}
		for i := fileseqGalopTransStart[c.state]; i < fileseqGalopTransStart[c.state+1]; i++ {
			k := fileseqGalopTransKind[i]
			if k != fileseqGalopKindAtom && k != fileseqGalopKindSet || !fileseqGalopMatches(i, t) {
				continue
			}
			if !group {
				intermediate.add(fileseqGalopConfig{fileseqGalopTransTarget[i], c.alt, c.ctx}, cp)
				continue
			}
			for j := fileseqGalopAfterStart[i]; j < fileseqGalopAfterStart[i+1]; j++ {
				intermediate.add(fileseqGalopConfig{fileseqGalopAfterState[j], c.alt, c.ctx}, cp)
			}
		}
	}
	if len(pr.skipped) == 0 && t != -1 {
		if alt := fileseqGalopUniqueAlt(intermediate.list); alt != 0 {
			return alt
		}
	}
	out.reset()
	pr.busy.reset()
	for _, c := range intermediate.list {
		pr.closure(c, out, t == -1, 0)
	}
	if t == -1 {
		// After EOF only configurations at the end of a rule matter.
		n := 0
		for _, c := range out.list {
			if fileseqGalopStateIsStop[c.state] {
				out.list[n] = c
				n++
			}
		}
		out.list = out.list[:n]
		out.at.reset()
		for i, c := range out.list {
			out.at.put(uint64(uint32(c.state))<<32|uint64(uint32(c.alt)), int32(i))
		}
	}
	if len(pr.skipped) > 0 {
		inStop := false
		for _, c := range out.list {
			if fileseqGalopStateIsStop[c.state] {
				inStop = true
				break
			}
		}
		if !pr.full || !inStop {
			for _, c := range pr.skipped {
				out.add(c, cp)
			}
		}
	}
	return 0
}

// subsets computes ANTLR's conflicting alternative subsets of list, a set's
// configurations (grouped by state and context). It returns the lowest
// alternative common to all subsets' minimums (0 if they differ), sets
// pr.multi when some subset has more than one alternative, and reports
// whether some state is associated with exactly one alternative.
func (pr *fileseqGalopPredictor) subsets(list []fileseqGalopConfig) (single int32, stateWithOneAlt bool) {
	// A configuration set holds one configuration per (state, alt), so two
	// configurations in the same (state, ctx) group always differ in alt.
	pr.groups.reset()
	pr.states.reset()
	pr.groupMin = pr.groupMin[:0]
	pr.stateAlt = pr.stateAlt[:0]
	pr.stateMulti = pr.stateMulti[:0]
	pr.multi = false
	for _, c := range list {
		g, isNew := pr.groups.put(uint64(uint32(c.state))<<32|uint64(uint32(c.ctx)), int32(len(pr.groupMin)))
		if isNew {
			pr.groupMin = append(pr.groupMin, c.alt)
		} else {
			pr.multi = true
			pr.groupMin[g] = min(pr.groupMin[g], c.alt)
		}
		s, isNew := pr.states.put(uint64(uint32(c.state)), int32(len(pr.stateAlt)))
		if isNew {
			pr.stateAlt = append(pr.stateAlt, c.alt)
			pr.stateMulti = append(pr.stateMulti, false)
		} else if pr.stateAlt[s] != c.alt {
			pr.stateMulti[s] = true
		}
	}
	for _, m := range pr.stateMulti {
		if !m {
			stateWithOneAlt = true
			break
		}
	}
	for _, m := range pr.groupMin {
		if single == 0 {
			single = m
		} else if single != m {
			return 0, stateWithOneAlt
		}
	}
	return single, stateWithOneAlt
}

// conflict reports whether SLL prediction stops at list, a set with more than
// one alternative: every configuration is at a rule's end, or the
// alternatives conflict (ANTLR's hasSLLConflictTerminatingPrediction).
func (pr *fileseqGalopPredictor) conflict(list []fileseqGalopConfig) bool {
	_, oneAlt := pr.subsets(list)
	return fileseqGalopAllInStop(list) || (pr.multi && !oneAlt)
}

func fileseqGalopAllInStop(list []fileseqGalopConfig) bool {
	for _, c := range list {
		if !fileseqGalopStateIsStop[c.state] {
			return false
		}
	}
	return true
}

// fileseqGalopDFAState is a state of a decision's SLL lookahead DFA, cached across
// parses as ANTLR caches its DFA. Walking existing edges takes no lock; new
// states are computed under fileseqGalopDFA.mu.
type fileseqGalopDFAState struct {
	configs  []fileseqGalopConfig
	alt      int32
	conflict int32
	// alts are a conflict's alternatives (bit a for alternative a), 0 when
	// one is past 63.
	alts  uint64
	edges []atomic.Pointer[fileseqGalopDFAState]
}

// fileseqGalopDFAGen is one generation of the SLL DFA cache: every decision's start
// state, the states by configurations, and the predictor whose context pool
// gives the configurations' contexts their meaning. Its pool is never reset,
// so cached configurations keep meaning the same contexts; the cache starts
// over by replacing the whole generation.
type fileseqGalopDFAGen struct {
	starts []atomic.Pointer[fileseqGalopDFAState]
	// precStarts are the start states of the decisions of left-recursive
	// rules, one per decision and precedence (see startAt), at
	// d*(fileseqGalopMaxPrec+1)+prec.
	precStarts []atomic.Pointer[fileseqGalopDFAState]
	states     map[string]*fileseqGalopDFAState
	pr         fileseqGalopPredictor
	key        []byte
}

// fileseqGalopDFA is the process's SLL DFA cache. Only the current generation grows.
// Once it holds fileseqGalopDFAMaxStates states or fileseqGalopDFAMaxContexts contexts, it is
// replaced by an empty one, and from then on it only serves the predictions
// already walking it: one that needs a state it lacks finishes uncached
// (predictSLLUncached). So no generation passes the bound (its contexts by at
// most one step's worth), and since the cache only saves work, no answer
// changes. peak is the most states a replaced generation held, and resets
// counts replacements.
//
// The full-context cache (fileseqGalopFullCache) stops growing instead of starting
// over: full-context predictions are rare, and an uncached one costs about
// what building its states does. SLL predictions are what every runtime
// decision makes, and a cache that stops growing leaves a long-lived process
// predicting uncached for whatever its first inputs did not reach. On a
// stream of 27,700 parses of distinct GALA code on one goroutine, stopping
// cost 1.25 times the time of an unbounded cache (3.3 times over tokens
// alone), starting over 1.02 times (1.8 times); both halve the peak memory or
// better. On eight goroutines, where new states wait for one lock, stopping
// was the faster (0.7 and 0.5 times, against 1.1 and 2.2).
var fileseqGalopDFA struct {
	mu     sync.Mutex
	gen    atomic.Pointer[fileseqGalopDFAGen]
	peak   int
	resets int
}

// fileseqGalopDFAMaxStates and fileseqGalopDFAMaxContexts bound each generation of the SLL DFA
// cache. They are read under fileseqGalopDFA.mu; set them before parsing starts, if at
// all. The defaults are three to four times what parsing the GALA compiler's
// sources and other GALA code over tokens alone (-Xno-brackets) leaves in the
// cache: about 16,000 states and 740,000 contexts, some 100 MB.
var (
	fileseqGalopDFAMaxStates   = 1 << 16
	fileseqGalopDFAMaxContexts = 1 << 21
)

// fileseqGalopDFAError marks an edge on which no alternative is viable.
var fileseqGalopDFAError = &fileseqGalopDFAState{}

// fileseqGalopNewDFAGen returns an empty generation of the SLL DFA cache.
func fileseqGalopNewDFAGen() *fileseqGalopDFAGen {
	g := &fileseqGalopDFAGen{starts: make([]atomic.Pointer[fileseqGalopDFAState], len(fileseqGalopDecisionState)), precStarts: make([]atomic.Pointer[fileseqGalopDFAState], len(fileseqGalopDecisionState)*(fileseqGalopMaxPrec+1)), states: map[string]*fileseqGalopDFAState{}}
	g.pr.pool.reset(true)
	return g
}

func init() {
	fileseqGalopDFA.gen.Store(fileseqGalopNewDFAGen())
}

// fileseqGalopDFAStats reports the SLL DFA cache: the states of the current
// generation, the most states any generation held, and how many times the
// cache started over.
func fileseqGalopDFAStats() (states, peak, resets int) {
	fileseqGalopDFA.mu.Lock()
	defer fileseqGalopDFA.mu.Unlock()
	states = len(fileseqGalopDFA.gen.Load().states)
	return states, max(fileseqGalopDFA.peak, states), fileseqGalopDFA.resets
}

// grows reports whether g may add to itself: it is the current generation
// and below its bound. Call it under fileseqGalopDFA.mu.
func (g *fileseqGalopDFAGen) grows() bool {
	return g == fileseqGalopDFA.gen.Load() && len(g.states) < fileseqGalopDFAMaxStates && len(g.pr.pool.kind) < fileseqGalopDFAMaxContexts
}

// checkFull replaces g, the current generation, with an empty one once it
// has reached its bound. Call it under fileseqGalopDFA.mu.
func (g *fileseqGalopDFAGen) checkFull() {
	if g != fileseqGalopDFA.gen.Load() || g.grows() {
		return
	}
	fileseqGalopDFA.peak = max(fileseqGalopDFA.peak, len(g.states))
	fileseqGalopDFA.resets++
	fileseqGalopDFA.gen.Store(fileseqGalopNewDFAGen())
}

// intern returns decision d's state in g for the configurations in set.
func (g *fileseqGalopDFAGen) intern(d int, set *fileseqGalopConfigSet) *fileseqGalopDFAState {
	return fileseqGalopInternState(g.states, &g.pr, &g.key, d, set, fileseqGalopEdges)
}

// fileseqGalopSortConfigs sorts configurations by state, then alternative: the order
// a cached state keeps them in.
func fileseqGalopSortConfigs(s []fileseqGalopConfig) {
	slices.SortFunc(s, func(a, b fileseqGalopConfig) int {
		if a.state != b.state {
			return int(a.state - b.state)
		}
		return int(a.alt - b.alt)
	})
}

// fileseqGalopInternState returns the state in states for the configurations in set,
// adding it if new. A state keeps its configurations sorted by state and
// alternative; its key is that list, after decision d when d >= 0. pr and key
// are scratch, owned by whoever owns states. A new state has edges edges.
func fileseqGalopInternState(states map[string]*fileseqGalopDFAState, pr *fileseqGalopPredictor, key *[]byte, d int, set *fileseqGalopConfigSet, edges int) *fileseqGalopDFAState {
	s := append(pr.sorted[:0], set.list...)
	pr.sorted = s
	fileseqGalopSortConfigs(s)
	k := (*key)[:0]
	if d >= 0 {
		k = binary.LittleEndian.AppendUint32(k, uint32(d))
	}
	for _, c := range s {
		k = binary.LittleEndian.AppendUint32(k, uint32(c.state))
		k = binary.LittleEndian.AppendUint32(k, uint32(c.alt))
		k = binary.LittleEndian.AppendUint32(k, uint32(c.ctx))
	}
	*key = k
	if st, ok := states[string(k)]; ok {
		return st
	}
	st := &fileseqGalopDFAState{configs: slices.Clone(s), edges: make([]atomic.Pointer[fileseqGalopDFAState], edges)}
	states[string(k)] = st
	return st
}

// startSLL puts the start configurations of decision d into cur (ANTLR's
// computeStartState in SLL mode).
func (pr *fileseqGalopPredictor) startSLL(d int, cur *fileseqGalopConfigSet) {
	pr.full = false
	cur.reset()
	pr.busy.reset()
	s := fileseqGalopDecisionState[d]
	pr.collect = true
	pr.filter, pr.rule = fileseqGalopDecisionLoopEntry[d], fileseqGalopStateRule[s]
	if pr.filter {
		pr.suppressed.reset()
	}
	for i := fileseqGalopTransStart[s]; i < fileseqGalopTransStart[s+1]; i++ {
		pr.closure(fileseqGalopConfig{fileseqGalopTransTarget[i], i - fileseqGalopTransStart[s] + 1, 0}, cur, false, 0)
	}
	pr.collect = false
	if pr.filter {
		pr.precedenceFilter(cur)
		pr.filter = false
	}
}

// precedenceFilter is ANTLR's applyPrecedenceFilter, for the start state of a
// left-recursive rule's loop entry: a configuration that leaves the loop is
// dropped where one that goes on in it (alternative 1) is at the same state
// with the same context, since leaving goes on in an enclosing invocation the
// same way, unless it got there past an outermost call of the rule. The
// precedence predicates of alternative 1 were evaluated by the closure.
func (pr *fileseqGalopPredictor) precedenceFilter(cur *fileseqGalopConfigSet) {
	pr.alt1.reset()
	for _, c := range cur.list {
		if c.alt == 1 {
			pr.alt1.put(uint64(uint32(c.state)), c.ctx)
		}
	}
	n := 0
	for _, c := range cur.list {
		if c.alt != 1 {
			_, spared := pr.suppressed.get(uint64(uint32(c.state))<<32 | uint64(uint32(c.alt)))
			if ctx, ok := pr.alt1.get(uint64(uint32(c.state))); ok && ctx == c.ctx && !spared {
				continue
			}
		}
		cur.list[n] = c
		n++
	}
	cur.list = cur.list[:n]
	cur.at.reset()
	for i, c := range cur.list {
		cur.at.put(uint64(uint32(c.state))<<32|uint64(uint32(c.alt)), int32(i))
	}
}

// stepSLL moves the configurations in cur over token t, or with group set
// over the bracketed group t opens (ANTLR's computeTargetState in SLL mode).
// It returns the state that ends the prediction (an alternative, an SLL
// conflict or fileseqGalopDFAError), or nil when the prediction goes on from the
// configurations in next.
func (pr *fileseqGalopPredictor) stepSLL(cur *fileseqGalopConfigSet, t int32, group bool, intermediate, next *fileseqGalopConfigSet) *fileseqGalopDFAState {
	if alt := pr.reach(cur, t, group, intermediate, next); alt != 0 {
		return &fileseqGalopDFAState{alt: alt}
	}
	if len(next.list) == 0 {
		return fileseqGalopDFAError
	}
	if alt := fileseqGalopUniqueAlt(next.list); alt != 0 {
		return &fileseqGalopDFAState{alt: alt}
	}
	if !pr.conflict(next.list) {
		return nil
	}
	// An SLL conflict: ANTLR's SLL answer is the lowest conflicting alternative.
	low := next.list[0].alt
	var alts uint64
	wide := false
	for _, c := range next.list {
		low = min(low, c.alt)
		if c.alt > 63 {
			wide = true
		} else {
			alts |= 1 << c.alt
		}
	}
	if wide {
		alts = 0
	}
	return &fileseqGalopDFAState{conflict: low, alts: alts}
}

// start returns decision d's start state in g, computing it once; nil when
// it is not cached and g may not grow.
func (g *fileseqGalopDFAGen) start(d int) *fileseqGalopDFAState {
	fileseqGalopDFA.mu.Lock()
	defer fileseqGalopDFA.mu.Unlock()
	if st := g.starts[d].Load(); st != nil {
		return st
	}
	if !g.grows() {
		return nil
	}
	cur := &g.pr.sets[0]
	g.pr.startSLL(d, cur)
	st := g.intern(d, cur)
	g.starts[d].Store(st)
	g.checkFull()
	return st
}

// startAt is start for decision d of a left-recursive rule, whose start state
// depends on the precedence prec its rule was called with: one cached state
// per precedence, as ANTLR's precedence DFA keeps.
func (g *fileseqGalopDFAGen) startAt(d int, prec int32) *fileseqGalopDFAState {
	at := &g.precStarts[d*(fileseqGalopMaxPrec+1)+int(prec)]
	if st := at.Load(); st != nil {
		return st
	}
	fileseqGalopDFA.mu.Lock()
	defer fileseqGalopDFA.mu.Unlock()
	if st := at.Load(); st != nil {
		return st
	}
	if !g.grows() {
		return nil
	}
	cur := &g.pr.sets[0]
	g.pr.prec = prec
	g.pr.startSLL(d, cur)
	st := g.intern(d, cur)
	at.Store(st)
	g.checkFull()
	return st
}

// next computes and caches the edge of from, a state of g, on symbol sym:
// token t, or with group set the bracketed group t opens. It returns nil
// when the edge is not cached and g may not grow.
func (g *fileseqGalopDFAGen) next(d int, from *fileseqGalopDFAState, sym int, t int32, group bool) *fileseqGalopDFAState {
	fileseqGalopDFA.mu.Lock()
	defer fileseqGalopDFA.mu.Unlock()
	if st := from.edges[sym].Load(); st != nil {
		return st
	}
	if !g.grows() {
		return nil
	}
	pr := &g.pr
	pr.full = false
	cur, intermediate, next := &pr.sets[0], &pr.sets[1], &pr.sets[2]
	cur.reset()
	for _, c := range from.configs {
		cur.add(c, &pr.pool)
	}
	st := pr.stepSLL(cur, t, group, intermediate, next)
	if st == nil {
		st = g.intern(d, next)
	}
	from.edges[sym].Store(st)
	g.checkFull()
	return st
}

// symbolAt reads the input at i for a prediction of decision d: the token t,
// its DFA symbol, whether that symbol is the bracketed group an opener at i
// starts (with p.group, as fileseqGalopBracketMatch paired them), and where the input
// after it starts.
func (p *fileseqGalopParser) symbolAt(d, i int) (t int32, sym int, isGroup bool, after int) {
	// The tokens end with EOF: the native flavor's run rejects a slice without
	// it, and the antlr flavor's NewfileseqGalopParser reads its stream up to EOF. EOF never
	// advances i, and a group jump lands just past its closer, on EOF at the
	// latest, so i stays in range.
	t = p.types[i]
	if t < -1 || int(t) > fileseqGalopMaxTokenType {
		p.noViableAlt(d)
	}
	if og := fileseqGalopOpenerSym[t+1]; p.group && og >= 0 && p.pairs[i] >= 0 {
		return t, fileseqGalopMaxTokenType + 2 + int(og), true, int(p.pairs[i]) + 1
	}
	if t != -1 {
		i++
	}
	return t, int(t) + 1, false, i
}

// peekAt notes that prediction read token i: peek is the furthest token an
// error replay's predictions read, as ANTLR's lazy token stream fetches
// them. i may be past EOF, which reads EOF (see fileseqGalopRecovery.read).
func (p *fileseqGalopParser) peekAt(i int) {
	if i > p.peek {
		p.peek = i
	}
}

// adaptivePredict predicts decision d as ANTLR's SLL prediction does, over
// the cached DFA, reading each bracketed group as one symbol unless p.group
// is off. That over-approximates SLL: every path over the tokens has a path
// over the groups, so an alternative ruled out here is ruled out in SLL and
// in LL, and a unique answer is ANTLR's. A conflict goes to onConflict with
// its smallest alternative: a first pass that succeeds with such choices is
// ANTLR's LL parse, and a wrong one is repaired. Where the cache may not grow
// (see fileseqGalopDFA), the prediction finishes uncached.
func (p *fileseqGalopParser) adaptivePredict(d int) int {
	p.stats.Predictions++
	g := fileseqGalopDFA.gen.Load()
	var st *fileseqGalopDFAState
	if fileseqGalopDecisionPrecedence[d] {
		st = g.startAt(d, p.prec)
	} else if st = g.starts[d].Load(); st == nil {
		st = g.start(d)
	}
	if st == nil {
		return p.predictSLLUncached(d)
	}
	for i := p.pos; ; {
		p.peekAt(i)
		t, sym, isGroup, after := p.symbolAt(d, i)
		next := st.edges[sym].Load()
		if next == nil {
			if next = g.next(d, st, sym, t, isGroup); next == nil {
				return p.predictSLLUncached(d)
			}
		}
		if alt, done := p.settleSLL(d, next); done {
			return alt
		}
		st, i = next, after
	}
}

// settleSLL ends a prediction of decision d at st when st ends it: with a
// syntax error (or ANTLR's fallback; see deadEnd), an alternative or a
// conflict.
func (p *fileseqGalopParser) settleSLL(d int, st *fileseqGalopDFAState) (int, bool) {
	switch {
	case st == fileseqGalopDFAError:
		return p.deadEnd(d), true
	case st.alt > 0:
		return int(st.alt), true
	case st.conflict > 0:
		return p.onConflict(d, int(st.conflict), st.alts), true
	}
	return 0, false
}

// predictSLLUncached predicts decision d as adaptivePredict does, with the
// parser's own predictor and no cache. Each step starts from the
// configurations sorted and added in the order a cached state keeps them, so
// it computes what the cache would.
func (p *fileseqGalopParser) predictSLLUncached(d int) int {
	pr := &p.pred
	pr.pool.reset(true)
	cur, intermediate, next := &pr.sets[0], &pr.sets[1], &pr.sets[2]
	pr.prec = p.prec
	pr.startSLL(d, next)
	for i := p.pos; ; {
		p.peekAt(i)
		s := append(pr.sorted[:0], next.list...)
		pr.sorted = s
		fileseqGalopSortConfigs(s)
		cur.reset()
		for _, c := range s {
			cur.add(c, &pr.pool)
		}
		t, _, isGroup, after := p.symbolAt(d, i)
		if st := pr.stepSLL(cur, t, isGroup, intermediate, next); st != nil {
			alt, _ := p.settleSLL(d, st)
			return alt
		}
		i = after
	}
}

// fileseqGalopEdges is the number of DFA edges per state: one per token type and EOF,
// then one per opening bracket for the group it opens.
const fileseqGalopEdges = fileseqGalopMaxTokenType + 2 + fileseqGalopOpenerCount

// fileseqGalopBracketMatch pairs the brackets of types into m: m[i] is the index of
// the closer of the opener at i, or -1. An opener with no well-nested closer
// (the input is not in the language) is left at -1, and prediction reads it
// as a token. A parse pairs brackets only when it reads groups (p.group).
// balanced says every bracket is paired: every sentence of the language is
// (see brackets), so input that is not cannot parse.
func fileseqGalopBracketMatch(types []int32, m []int32) (pairs []int32, balanced bool) {
	m = slices.Grow(m[:0], len(types))[:len(types)]
	var open []int32
	balanced = true
	for i, t := range types {
		m[i] = -1
		if t < -1 || int(t) > fileseqGalopMaxTokenType {
			continue
		}
		if fileseqGalopOpenerSym[t+1] >= 0 {
			open = append(open, int32(i))
			continue
		}
		if !fileseqGalopIsCloser[t+1] {
			continue
		}
		if len(open) == 0 {
			balanced = false
			continue
		}
		top := open[len(open)-1]
		if fileseqGalopOpenerCloser[fileseqGalopOpenerSym[types[top]+1]] == t {
			m[top] = int32(i)
			open = open[:len(open)-1]
		} else {
			// A closer of the wrong kind: no opener still open can close
			// around it.
			open = open[:0]
			balanced = false
		}
	}
	return m, balanced && len(open) == 0
}

// onConflict settles an SLL conflict whose lowest conflicting alternative is
// sllAlt and whose alternatives are alts (0 when one is past 63). The SLL
// pass takes sllAlt; this stays small enough to inline.
func (p *fileseqGalopParser) onConflict(d int, sllAlt int, alts uint64) int {
	if p.ll || p.rp.on || p.first {
		return p.onConflictSlow(d, sllAlt, alts)
	}
	p.rp.seen++
	return sllAlt
}

// onConflictSlow is onConflict outside the SLL pass: a guessing first pass
// records the conflict as a guess point (see guessSource), LL mode runs
// full-context prediction, and a repair pass replays a recorded conflict or
// records a new one.
func (p *fileseqGalopParser) onConflictSlow(d int, sllAlt int, alts uint64) int {
	if p.first {
		if alts == 0 {
			p.gs.wide = true
			return sllAlt
		}
		return p.guess(alts)
	}
	if p.ll {
		if alt := p.rp.knownAt(d, p.pos, p.stack); alt > 0 {
			return alt
		}
		return p.predictLL(d)
	}
	r := &p.rp
	i := r.seq
	r.seq++
	if i < len(r.recs) {
		c := &r.recs[i]
		if int(c.d) != d || int(c.pos) != p.pos {
			panic("galop: a repair pass left the parse it replays")
		}
		return int(c.alt)
	}
	from := len(r.stacks)
	r.stacks = append(r.stacks, p.stack...)
	r.recs = append(r.recs, fileseqGalopConflict{d: int32(d), pos: int32(p.pos), alt: int32(sllAlt), stackFrom: int32(from), stackTo: int32(len(r.stacks))})
	return sllAlt
}

// fileseqGalopConflict is an SLL conflict a repair pass met: the decision, the token
// it was predicted at, the alternative the parse takes there, the parser's
// call stack at that point (r.stacks[stackFrom:stackTo]), and its LL answer
// once known (0: not checked, -1: no alternative is viable, err says why).
type fileseqGalopConflict struct {
	d, pos, alt, known int32
	stackFrom, stackTo int32
	err                error
}

// fileseqGalopRepair is the state of a repair (see llParse): how many conflicts the
// SLL pass met, and the records and progress of the repair passes.
type fileseqGalopRepair struct {
	seen   int
	on     bool
	seq    int
	recs   []fileseqGalopConflict
	stacks []int32
	// byPos indexes recs by decision and token while an error replay (see
	// antlrError) reads their LL answers; nil otherwise.
	byPos map[uint64][]int32
}

// indexRecs indexes recs by decision and token for knownAt.
func (r *fileseqGalopRepair) indexRecs() {
	r.byPos = make(map[uint64][]int32, len(r.recs))
	for i, c := range r.recs {
		k := uint64(c.pos)<<32 | uint64(c.d)
		r.byPos[k] = append(r.byPos[k], int32(i))
	}
}

// knownAt is the LL answer a repair recorded for decision d at token pos with
// call stack stack, or 0.
func (r *fileseqGalopRepair) knownAt(d, pos int, stack []int32) int {
	for _, i := range r.byPos[uint64(pos)<<32|uint64(d)] {
		c := &r.recs[i]
		if c.known > 0 && slices.Equal(r.stacks[c.stackFrom:c.stackTo], stack) {
			return int(c.known)
		}
	}
	return 0
}

// A repair stops and falls back to the whole-input LL rerun when the passes
// after the first would replay more tokens in total than the input holds, so
// that a file it cannot repair costs about two SLL passes more than the rerun;
// fileseqGalopRepairPasses also bounds the number of passes. fileseqGalopRepairBackward is how
// many conflicts a pass checks backwards from its error before it checks the
// rest forwards from the start, as LL mode meets them. The conflict to switch
// is almost always within a few of the error (on the GALA and held-out
// corpora and 10,000 mutants of them, at most 5 back), and a parse that fails
// for good makes at most fileseqGalopRepairBackward full-context predictions more than
// the rerun would.
const (
	fileseqGalopRepairPasses   = 8
	fileseqGalopRepairBackward = 8
)

// llParse returns the parse ANTLR's LL prediction gives, after the SLL pass
// failed with sllErr. With repair it repairs the failed parse instead of
// running full-context prediction at every conflict; repair needs an entry
// rule that ends with EOF.
//
// At an SLL conflict, ANTLR's LL prediction is the lowest alternative that
// can still complete the parse: configurations with the same state and stack
// have the same future, and SLL configurations over-approximate LL ones. So a
// parse that reaches EOF proves its choice at every conflict where it took the
// lowest alternative, and only where it takes another one does it need LL
// prediction, which then decides. Each pass replays the parse with the
// choices so far; after a syntax error, switchConflict changes one. When it
// finds nothing to change, LL fails too: at the earliest conflict where no
// alternative is viable, or where this pass failed.
func (p *fileseqGalopParser) llParse(rule func(*fileseqGalopParser) int32, repair bool, sllErr error) (int32, error) {
	if p.ll {
		// The failed pass ran in LL mode already (see llFirst).
		return -1, sllErr
	}
	if repair {
		if p.rp.seen == 0 {
			// No conflict before the error: every decision was LL's, so LL
			// mode fails at the same token.
			return -1, sllErr
		}
		r := &p.rp
		r.on = true
		defer func() { r.on = false }()
		r.recs, r.stacks = r.recs[:0], r.stacks[:0]
		replayed := 0 // tokens up to the errors of the failed passes after the first
		for pass := 0; pass < fileseqGalopRepairPasses; pass++ {
			r.seq = 0
			root, err := p.attempt(rule)
			if err == nil {
				return root, nil
			}
			if pass > 0 {
				replayed += p.pos
			}
			switched, dead := p.switchConflict()
			// The next pass replays about as far as this one did.
			if switched && replayed+p.pos > len(p.types) {
				break
			}
			switch {
			case switched:
			case dead != nil:
				// LL mode stops at that conflict; so does the parse.
				p.pos = int(dead.pos)
				return -1, dead.err
			default:
				return root, err
			}
		}
		r.on = false
	}
	p.ll = true
	defer func() { p.ll = false }()
	return p.attempt(rule)
}

// switchConflict checks the conflicts of the pass that just failed and
// switches one whose LL answer differs from the alternative taken: the latest
// such among the fileseqGalopRepairBackward before the error, or else the earliest of
// the rest. When none differs it returns the earliest conflict where no
// alternative is viable, if any: there LL mode fails. (Scanning backwards,
// the last dead one seen is the earliest; the forward scan returns its first.)
func (p *fileseqGalopParser) switchConflict() (switched bool, dead *fileseqGalopConflict) {
	r := &p.rp
	budget := fileseqGalopRepairBackward
	i := r.seq - 1
	for ; i >= 0; i-- {
		c := &r.recs[i]
		if c.known == 0 {
			if budget == 0 {
				break
			}
			budget--
			p.checkConflict(c)
		}
		switch {
		case c.known < 0:
			dead = c
		case c.known != c.alt:
			p.switchTo(i)
			return true, nil
		}
	}
	// Forwards over the conflicts the backward scan did not check. A dead
	// one with only agreeing conflicts before it is where LL mode fails.
	for j := 0; j <= i; j++ {
		c := &r.recs[j]
		if c.known == 0 {
			p.checkConflict(c)
		}
		switch {
		case c.known < 0:
			return false, c
		case c.known != c.alt:
			p.switchTo(j)
			return true, nil
		}
	}
	return false, dead
}

// switchTo makes conflict i take its LL answer and drops the records after
// it, which the next pass records again.
func (p *fileseqGalopParser) switchTo(i int) {
	r := &p.rp
	c := &r.recs[i]
	c.alt = c.known
	r.recs, r.stacks = r.recs[:i+1], r.stacks[:c.stackTo]
}

// checkConflict computes c's LL answer with the parser at c's token and stack.
func (p *fileseqGalopParser) checkConflict(c *fileseqGalopConflict) {
	pos, stack := p.pos, p.stack
	defer func() {
		p.pos, p.stack = pos, stack
		if e := recover(); e != nil {
			se, ok := e.(*FileseqSyntaxError)
			if !ok {
				panic(e)
			}
			c.known, c.err = -1, se
		}
	}()
	p.pos, p.stack = int(c.pos), p.rp.stacks[c.stackFrom:c.stackTo:c.stackTo]
	c.known = int32(p.predictLL(int(c.d)))
}

// fileseqGalopGuess is a guess point of the first pass: the alternatives no test
// ruled out (bit a for alternative a) and the one taken.
type fileseqGalopGuess struct {
	alts uint64
	cur  uint8
}

// fileseqGalopGuesses records the guess points of the first pass: seq counts those met
// by the current pass, the first forced of pts replay their choice, and wide
// says a guess point had an alternative past 63, which the search cannot record.
type fileseqGalopGuesses struct {
	seq    int
	forced int
	pts    []fileseqGalopGuess
	wide   bool
}

// The search stops after fileseqGalopGuessReplays replays; once its replays have read
// fileseqGalopGuessTokens times the input's tokens, or fileseqGalopGuessFloor tokens for a short
// input (a replay rereads the input from its start, so k wrong guesses far into
// a large input cost k passes); or after fileseqGalopGuessStall replays in a row that
// fail no further into the input than the furthest failure so far. A search
// that will succeed fixes its wrong guesses one by one and gets further with
// each; on input outside the language every replay fails about where the
// first pass did. Stopping early is always exact: what follows the search is.
const (
	fileseqGalopGuessReplays = 64
	fileseqGalopGuessTokens  = 4
	fileseqGalopGuessFloor   = 16384
	fileseqGalopGuessStall   = 16
)

// guess takes the smallest alternative in alts, through guessPoint when alts
// has more than one. It stays small enough to inline.
func (p *fileseqGalopParser) guess(alts uint64) int {
	if alts&(alts-1) == 0 {
		return bits.TrailingZeros64(alts)
	}
	return p.guessPoint(alts)
}

// guessPoint records a guess point and takes its smallest alternative, or
// replays the choice the search forces there.
func (p *fileseqGalopParser) guessPoint(alts uint64) int {
	g := &p.gs
	i := g.seq
	g.seq++
	if i < g.forced {
		return int(g.pts[i].cur)
	}
	low := bits.TrailingZeros64(alts)
	g.pts = append(g.pts[:i], fileseqGalopGuess{alts: alts, cur: uint8(low)})
	return low
}

// guessed says the first pass made a guess, so it may have taken another
// path than SLL prediction would.
func (g *fileseqGalopGuesses) guessed() bool {
	return len(g.pts) > 0 || g.wide
}

// next makes the latest guess point with an untried alternative take the
// next one, forcing the choices before it; false when none is left.
func (g *fileseqGalopGuesses) next() bool {
	for j := min(g.seq, len(g.pts)) - 1; j >= 0; j-- {
		pt := &g.pts[j]
		if rest := pt.alts &^ (uint64(2)<<pt.cur - 1); rest != 0 {
			pt.cur = uint8(bits.TrailingZeros64(rest))
			g.pts = g.pts[:j+1]
			g.forced = j + 1
			return true
		}
	}
	return false
}

// search replays the failed first pass with the next choice sequences, as
// described above; ok is false when it stopped without a parse.
func (p *fileseqGalopParser) search(rule func(*fileseqGalopParser) int32) (root int32, ok bool) {
	g := &p.gs
	defer func() { g.forced, g.pts = 0, g.pts[:0] }()
	budget := max(fileseqGalopGuessTokens*len(p.types), fileseqGalopGuessFloor)
	furthest, stall := p.pos, 0
	for replays := 0; replays < fileseqGalopGuessReplays && !g.wide && g.next(); replays++ {
		root, err := p.attempt(rule)
		if err == nil {
			return root, true
		}
		if budget -= p.pos + 1; budget <= 0 {
			break
		}
		if p.pos > furthest {
			furthest, stall = p.pos, 0
		} else if stall++; stall >= fileseqGalopGuessStall {
			break
		}
	}
	return -1, false
}

// guessOr guesses decision d among alts in the first pass and its search,
// and predicts it otherwise (in a repair or LL pass, or reporting an error:
// the first pass is over by then).
func (p *fileseqGalopParser) guessOr(d int, alts uint64) int {
	if p.first {
		return p.guess(alts)
	}
	return p.adaptivePredict(d)
}

// startLL fills cur with the closure of decision d's alternatives, with the
// call stack stack as the outer context (ANTLR's start state of full-context
// prediction).
func (pr *fileseqGalopPredictor) startLL(d int, stack []int32, cur *fileseqGalopConfigSet) {
	cp := &pr.pool
	outer := int32(0)
	for _, ret := range stack {
		outer = cp.singleton(outer, ret)
	}
	cur.reset()
	pr.busy.reset()
	s := fileseqGalopDecisionState[d]
	pr.collect = true
	for i := fileseqGalopTransStart[s]; i < fileseqGalopTransStart[s+1]; i++ {
		pr.closure(fileseqGalopConfig{fileseqGalopTransTarget[i], i - fileseqGalopTransStart[s] + 1, outer}, cur, false, 0)
	}
	pr.collect = false
}

// stepLL moves full-context prediction from cur past token t into next and
// applies ANTLR's stopping rule: the alternative it picks, -1 when no
// alternative is viable, or 0 to read another token.
func (pr *fileseqGalopPredictor) stepLL(cur *fileseqGalopConfigSet, t int32, intermediate, next *fileseqGalopConfigSet) int32 {
	if alt := pr.reach(cur, t, false, intermediate, next); alt != 0 {
		return alt
	}
	if len(next.list) == 0 {
		return -1
	}
	if alt := fileseqGalopUniqueAlt(next.list); alt != 0 {
		return alt
	}
	alt, _ := pr.subsets(next.list)
	return alt
}

// predictLLUncached runs ANTLR's full-context prediction of decision d from
// the current token, with the parser's call stack as the outer context.
func (p *fileseqGalopParser) predictLLUncached(d int) int {
	pr := &p.pred
	pr.full = true
	pr.pool.reset(false)
	cur, intermediate, next := &pr.sets[0], &pr.sets[1], &pr.sets[2]
	pr.prec = p.prec
	pr.startLL(d, p.stack, cur)
	for offset := 0; ; {
		p.peekAt(p.pos + offset)
		t := p.la(offset + 1)
		switch alt := pr.stepLL(cur, t, intermediate, next); {
		case alt < 0:
			p.llBad = true
			p.noViableAlt(d)
		case alt > 0:
			return int(alt)
		}
		cur, next = next, cur
		if t != -1 {
			offset++
		}
	}
}

// fileseqGalopFullCache is the full-context prediction cache. For a
// decision and a call stack, ANTLR's full-context prediction depends only on
// the tokens ahead, so it is cached like the SLL DFA, as a DFA per (decision,
// stack): states are configuration sets whose contexts live in the
// cache's pool, which is never reset, so they keep their meaning.
// Finding a cached start state takes a read lock and walking cached edges no
// lock; new states are computed under the write lock. Past fileseqGalopFullMaxStates
// states or fileseqGalopFullMaxContexts contexts the cache stops growing, and
// prediction it cannot answer runs uncached. (Starting over instead thrashes
// when the predictions in use outgrow it, and building cached states costs
// more than predicting uncached.)
type fileseqGalopFullCache struct {
	mu     sync.RWMutex
	full   atomic.Bool
	starts map[string]*fileseqGalopDFAState
	states map[string]*fileseqGalopDFAState
	pr     fileseqGalopPredictor
	key    []byte // scratch for state keys
}

// fileseqGalopFullMaxStates and fileseqGalopFullMaxContexts bound the cache.
const (
	fileseqGalopFullMaxStates   = 1 << 15
	fileseqGalopFullMaxContexts = 1 << 20
)

// fileseqGalopFull is the process's full-context prediction cache.
var fileseqGalopFull = func() *fileseqGalopFullCache {
	g := &fileseqGalopFullCache{starts: map[string]*fileseqGalopDFAState{}, states: map[string]*fileseqGalopDFAState{}}
	g.pr.pool.reset(false)
	g.pr.full = true
	return g
}()

// isFull says whether g has stopped growing, and records it in g.full; call
// it under the write lock.
func (g *fileseqGalopFullCache) isFull() bool {
	if len(g.states) >= fileseqGalopFullMaxStates || len(g.pr.pool.kind) >= fileseqGalopFullMaxContexts {
		g.full.Store(true)
	}
	return g.full.Load()
}

// start returns the start state of decision d under the call stack whose key
// (the decision, then the stack) is key, or nil when it is not cached and
// the cache is full.
func (g *fileseqGalopFullCache) start(d int, stack []int32, key []byte, prec int32) *fileseqGalopDFAState {
	g.mu.RLock()
	st, ok := g.starts[string(key)]
	g.mu.RUnlock()
	if ok || g.full.Load() {
		return st
	}
	g.mu.Lock()
	defer g.mu.Unlock()
	if st, ok := g.starts[string(key)]; ok {
		return st
	}
	if g.isFull() {
		return nil
	}
	g.pr.prec = prec
	g.pr.startLL(d, stack, &g.pr.sets[0])
	st = fileseqGalopInternState(g.states, &g.pr, &g.key, -1, &g.pr.sets[0], fileseqGalopMaxTokenType+2)
	g.starts[string(key)] = st
	return st
}

// next computes and caches the edge of from on token t; nil when the cache
// is full.
func (g *fileseqGalopFullCache) next(from *fileseqGalopDFAState, t int32) *fileseqGalopDFAState {
	if g.full.Load() {
		return from.edges[t+1].Load()
	}
	g.mu.Lock()
	defer g.mu.Unlock()
	if st := from.edges[t+1].Load(); st != nil {
		return st
	}
	if g.isFull() {
		return nil
	}
	pr := &g.pr
	cur, intermediate, next := &pr.sets[0], &pr.sets[1], &pr.sets[2]
	cur.reset()
	for _, c := range from.configs {
		cur.add(c, &pr.pool)
	}
	var st *fileseqGalopDFAState
	switch alt := pr.stepLL(cur, t, intermediate, next); {
	case alt < 0:
		st = fileseqGalopDFAError
	case alt > 0:
		st = &fileseqGalopDFAState{alt: alt}
	default:
		st = fileseqGalopInternState(g.states, pr, &g.key, -1, next, fileseqGalopMaxTokenType+2)
	}
	from.edges[t+1].Store(st)
	return st
}

// predictLL runs ANTLR's full-context prediction of decision d from the
// current token, with the parser's call stack as the outer context, through
// the cache when it can.
func (p *fileseqGalopParser) predictLL(d int) int {
	p.stats.FullContext++
	key := binary.LittleEndian.AppendUint32(p.llKey[:0], uint32(d))
	for _, ret := range p.stack {
		key = binary.LittleEndian.AppendUint32(key, uint32(ret))
	}
	if fileseqGalopDecisionPrecedence[d] {
		// A left-recursive rule's decision starts from its precedence.
		key = binary.LittleEndian.AppendUint32(key, uint32(p.prec)|1<<31)
	}
	p.llKey = key
	st := fileseqGalopFull.start(d, p.stack, key, p.prec)
	for i := 1; st != nil; i++ {
		p.peekAt(p.pos + i - 1)
		t := p.la(i)
		if t < -1 || int(t)+1 >= len(st.edges) {
			break
		}
		next := st.edges[t+1].Load()
		if next == nil {
			if next = fileseqGalopFull.next(st, t); next == nil {
				break
			}
		}
		switch {
		case next == fileseqGalopDFAError:
			p.llBad = true
			p.noViableAlt(d)
		case next.alt > 0:
			return int(next.alt)
		}
		st = next
	}
	return p.predictLLUncached(d)
}

// Kinds of decisions in fileseqGalopDecisionKind, and of Sync in fileseqGalopStateSync.
const (
	fileseqGalopDecisionAlt    = 0
	fileseqGalopDecisionOpt    = 1
	fileseqGalopDecisionStar   = 2
	fileseqGalopDecisionPlus   = 3
	fileseqGalopSyncBlockStart = 1
	fileseqGalopSyncLoopBack   = 2
)

// fileseqGalopExpected is a set of token types, EOF included, being collected for an
// error message.
type fileseqGalopExpected struct {
	in []bool // indexed by token type + 1
}

// fileseqGalopNewExpected is an empty fileseqGalopExpected.
func fileseqGalopNewExpected() *fileseqGalopExpected {
	return &fileseqGalopExpected{in: make([]bool, fileseqGalopMaxTokenType+2)}
}

func (x *fileseqGalopExpected) add(set []int32) {
	for i := 0; i < len(set); i += 2 {
		for t := set[i]; t <= set[i+1]; t++ {
			x.in[t+1] = true
		}
	}
}

// has reports whether t is in the set; a type outside the vocabulary never is.
func (x *fileseqGalopExpected) has(t int32) bool {
	return t+1 >= 0 && int(t+1) < len(x.in) && x.in[t+1]
}

// String renders the set as ANTLR's IntervalSet.StringVerbose: one name, or
// names in type order between braces.
func (x *fileseqGalopExpected) String() string {
	var names []string
	for i, ok := range x.in {
		if !ok {
			continue
		}
		if i == 0 {
			names = append(names, "<EOF>")
		} else {
			names = append(names, fileseqGalopTokenDisplay[i-1])
		}
	}
	if len(names) == 1 {
		return names[0]
	}
	return "{" + strings.Join(names, ", ") + "}"
}

// fileseqGalopEmuError is an error ANTLR reports: its message, at token at. A
// prediction that found no viable alternative (noViable) started at token
// start, which ANTLR's NoViableAltException records.
type fileseqGalopEmuError struct {
	at       int
	msg      string
	noViable bool
	start    int
}

// fileseqGalopEmu replays ANTLR's parse of the parser's tokens; see errorsSource.
// fallbacks are the alternatives its predictions fell back on.
type fileseqGalopEmu struct {
	p         *fileseqGalopParser
	pending   *fileseqGalopEmuError
	sll       fileseqGalopSLLFailure
	fallbacks []fileseqGalopFallback
	// precs are the precedences of the rule calls on the parser's stack;
	// a grammar without left recursion keeps none (all are 0).
	precs []int32
}

// fileseqGalopFallback is a prediction of decision d at token pos that found no
// viable alternative, where ANTLR predicts alt instead of failing (see
// sllFailure).
type fileseqGalopFallback struct {
	d, pos, prec, alt int32
}

// deadEnd is a prediction of decision d that found no viable alternative at
// the current token: a syntax error, unless antlrError found that ANTLR falls
// back on an alternative there.
func (p *fileseqGalopParser) deadEnd(d int) int {
	for _, f := range p.fallbacks {
		if int(f.d) == d && int(f.pos) == p.pos && (!fileseqGalopDecisionPrecedence[d] || f.prec == p.prec) {
			return int(f.alt)
		}
	}
	p.noViableAlt(d)
	return 0
}

// antlrError replaces err, the final parse's syntax error, with the first
// error ANTLR reports parsing the same tokens from rule's start state. The
// replay predicts over the tokens alone, never over bracketed groups. The
// parser's position is left where the failed parse left it.
//
// ANTLR may report no error at all: where its prediction finds no viable
// alternative after one had left the decision's rule, it takes that one and
// parses on, and an entry rule that does not end with EOF can then stop
// early, without error. antlrError then returns nil and leaves the
// alternatives ANTLR fell back on in p.fallbacks, for deadEnd to take.
func (p *fileseqGalopParser) antlrError(start int32, err error) error {
	// Most inputs that reach here have a syntax error and store nothing, so
	// the key is built only once the cache holds something.
	if fileseqGalopFallbackCount.Load() > 0 {
		if key := fileseqGalopFallbackKey(start, p.types); key != "" {
			if f, ok := fileseqGalopFallbackCache.Load(key); ok {
				p.fallbacks = f.([]fileseqGalopFallback)
				return nil
			}
		}
	}
	pos, ll, group := p.pos, p.ll, p.group
	defer func() { p.pos, p.ll, p.group = pos, ll, group }()
	p.ll, p.group, p.fallbacks = true, false, nil
	// Conflicts the repair checked need no full-context prediction again.
	if len(p.rp.recs) > 0 {
		p.rp.indexRecs()
		defer func() { p.rp.byPos = nil }()
	}
	e := fileseqGalopEmu{p: p}
	switch found := e.run(start); {
	case found != nil:
		return p.syntaxErrorAt(found.at, found.msg)
	case len(e.fallbacks) > 0:
		p.fallbacks = e.fallbacks
		if key := fileseqGalopFallbackKey(start, p.types); key != "" && fileseqGalopFallbackCount.Add(1) <= fileseqGalopFallbackMax {
			fileseqGalopFallbackCache.Store(key, e.fallbacks)
		}
		return nil
	}
	return err
}

// fileseqGalopFallbackCache holds, by entry rule and token types, the alternatives
// antlrError found ANTLR's prediction falling back on where the parse reports
// no error. The replay reads token types alone, so its answer is the same for
// any input with the same types, as an SLL DFA state is; the cache spares
// inputs of one shape replaying it again. It keeps at most fileseqGalopFallbackMax
// answers, for inputs of at most fileseqGalopFallbackMaxTokens tokens, and never
// forgets one.
var (
	fileseqGalopFallbackCache     sync.Map
	fileseqGalopFallbackCount     atomic.Int64
	fileseqGalopFallbackMax       = int64(1 << 12)
	fileseqGalopFallbackMaxTokens = 1 << 10
)

// fileseqGalopFallbackKey is the cache key of a replay from start over types, or ""
// for an input too long to cache.
func fileseqGalopFallbackKey(start int32, types []int32) string {
	if len(types) > fileseqGalopFallbackMaxTokens {
		return ""
	}
	k := binary.LittleEndian.AppendUint32(make([]byte, 0, 4*len(types)+4), uint32(start))
	for _, t := range types {
		k = binary.LittleEndian.AppendUint32(k, uint32(t))
	}
	return string(k)
}

// expected is ANTLR's getExpectedTokens at state s with the parser's stack:
// what can follow s, through the rules on the stack while their ends can be
// reached, and EOF past the outermost.
func (e *fileseqGalopEmu) expected(s int32) *fileseqGalopExpected {
	x := fileseqGalopNewExpected()
	x.add(fileseqGalopTokenSets[fileseqGalopStateNext[s]])
	reaches := fileseqGalopStateReachesEnd[s]
	for i := len(e.p.stack) - 1; i >= 0 && reaches; i-- {
		f := e.p.stack[i]
		x.add(fileseqGalopTokenSets[fileseqGalopStateNext[f]])
		reaches = fileseqGalopStateReachesEnd[f]
	}
	if reaches {
		x.in[0] = true
	}
	return x
}

// fileseqGalopQuote is ANTLR's escapeWSAndQuote.
func fileseqGalopQuote(s string) string {
	s = strings.ReplaceAll(s, "\t", "\\t")
	s = strings.ReplaceAll(s, "\n", "\\n")
	s = strings.ReplaceAll(s, "\r", "\\r")
	return "'" + s + "'"
}

// report is ANTLR's "<what> input <token> expecting <set>" at the current token.
func (e *fileseqGalopEmu) report(what string, exp *fileseqGalopExpected) *fileseqGalopEmuError {
	pos := e.p.pos
	return &fileseqGalopEmuError{at: pos, msg: what + " input " + fileseqGalopQuote(e.p.tokenDisplay(pos)) + " expecting " + exp.String()}
}

func (e *fileseqGalopEmu) noViable(start, off int) *fileseqGalopEmuError {
	input := "<EOF>"
	if e.p.types[start] != FileseqEOF {
		input = e.p.inputText(start, off)
	}
	return &fileseqGalopEmuError{at: off, msg: "no viable alternative at input " + fileseqGalopQuote(input), noViable: true, start: start}
}

// How ANTLR's RecoverInline and Sync recover (see inlineFix and syncFix):
// the token fits (Sync only), the current token is deleted, the missing
// token is inserted (RecoverInline only), the input is skipped to what can
// follow (Sync at a loop back), or a mismatch is left pending.
const (
	fileseqGalopFixNone = iota
	fileseqGalopFixDelete
	fileseqGalopFixInsert
	fileseqGalopFixSkip
	fileseqGalopFixMismatch
)

// inlineFix is how ANTLR's RecoverInline recovers at match state s, whose
// transition leads to next, with exp, the tokens expected at s, and the
// error it reports or, for a mismatch, sets. The first-error replay and the
// recovering parse both decide with it.
func (e *fileseqGalopEmu) inlineFix(s, next int32) (fix int, exp *fileseqGalopExpected, err *fileseqGalopEmuError) {
	exp = e.expected(s)
	switch {
	case exp.has(e.la2()):
		return fileseqGalopFixDelete, exp, e.report("extraneous", exp)
	case e.expected(next).has(e.p.la(1)):
		pos := e.p.pos
		return fileseqGalopFixInsert, exp, &fileseqGalopEmuError{at: pos, msg: "missing " + exp.String() + " at " + fileseqGalopQuote(e.p.tokenDisplay(pos))}
	}
	return fileseqGalopFixMismatch, exp, e.report("mismatched", exp)
}

// syncFix is how ANTLR's Sync recovers at s, a block start or a loop back
// (outside error recovery mode), like inlineFix.
func (e *fileseqGalopEmu) syncFix(s int32, blockStart bool) (fix int, exp *fileseqGalopExpected, err *fileseqGalopEmuError) {
	if fileseqGalopStateReachesEnd[s] || fileseqGalopInSet(fileseqGalopTokenSets[fileseqGalopStateNext[s]], e.p.la(1)) {
		return fileseqGalopFixNone, nil, nil
	}
	exp = e.expected(s)
	switch {
	case !blockStart:
		return fileseqGalopFixSkip, exp, e.report("extraneous", exp)
	case exp.has(e.la2()):
		return fileseqGalopFixDelete, exp, e.report("extraneous", exp)
	}
	return fileseqGalopFixMismatch, exp, e.report("mismatched", exp)
}

// recoverInline is ANTLR's RecoverInline at match state s, whose transition
// leads to next: an error it reports is returned, a mismatch it only sets
// becomes pending.
func (e *fileseqGalopEmu) recoverInline(s, next int32) *fileseqGalopEmuError {
	fix, _, err := e.inlineFix(s, next)
	if fix == fileseqGalopFixMismatch {
		e.pending = err
		return nil
	}
	return err
}

// sync is ANTLR's Sync at s, of a block start or a loop back, followed by the
// generated code's error check if check is set: an error it reports is
// returned; a mismatch at a block start becomes pending.
func (e *fileseqGalopEmu) sync(s int32, blockStart, check bool) *fileseqGalopEmuError {
	switch fix, _, err := e.syncFix(s, blockStart); fix {
	case fileseqGalopFixNone:
	case fileseqGalopFixMismatch:
		e.pending = err
	default:
		return err
	}
	if check {
		return e.pending
	}
	return nil
}

// la2 is LA(2), which makes ANTLR's token stream read the token after the
// current one.
func (e *fileseqGalopEmu) la2() int32 {
	e.p.peekAt(e.p.pos + 1)
	return e.p.la(2)
}

// ll1Alt is the alternative of decision d whose lookahead has LA(1), or 0.
func (e *fileseqGalopEmu) ll1Alt(d int) int {
	t := e.p.la(1)
	for i := fileseqGalopAltLookStart[d]; i < fileseqGalopAltLookStart[d+1]; i++ {
		if fileseqGalopInSet(fileseqGalopTokenSets[fileseqGalopAltLook[i]], t) {
			return int(i-fileseqGalopAltLookStart[d]) + 1
		}
	}
	return 0
}

func (e *fileseqGalopEmu) consume() {
	if e.p.types[e.p.pos] != FileseqEOF {
		e.p.pos++
	}
}

// run replays ANTLR from state s, a rule's start, and returns the first
// error it reports, or nil.
func (e *fileseqGalopEmu) run(s int32) *fileseqGalopEmuError {
	p := e.p
	p.pos = 0
	p.stack = p.stack[:0]
	e.precs = e.precs[:0]
	// back says the walk just left a loop back, which synced already: a
	// loop's next iteration does not sync at its start.
	back := false
	for {
		fromBack := back
		back = false
		if fileseqGalopStateIsStop[s] {
			// The end of a rule function checks for an error.
			if e.pending != nil {
				return e.pending
			}
			if len(p.stack) == 0 {
				return nil
			}
			s = p.stack[len(p.stack)-1]
			p.stack = p.stack[:len(p.stack)-1]
			if fileseqGalopMaxPrec > 0 {
				e.precs = e.precs[:len(e.precs)-1]
			}
			continue
		}
		if d := int(fileseqGalopStateDecision[s]); d >= 0 {
			// ANTLR matches the alternatives of a set decision as one set.
			if after := fileseqGalopDecisionSetAfter[d]; after >= 0 {
				if e.ll1Alt(d) > 0 {
					e.consume()
				} else if err := e.recoverInline(s, after); err != nil {
					return err
				}
				s = after
				continue
			}
			alt, err := e.decide(d, s, fromBack)
			if err != nil {
				return err
			}
			back = fileseqGalopDecisionKind[d] == fileseqGalopDecisionPlus && alt == int(fileseqGalopDecisionLoopAlt[d])
			s = fileseqGalopTransTarget[fileseqGalopTransStart[s]+int32(alt)-1]
			continue
		}
		switch fileseqGalopStateSync[s] {
		case fileseqGalopSyncLoopBack:
			if err := e.sync(s, false, true); err != nil {
				return err
			}
			back = true
		case fileseqGalopSyncBlockStart:
			if !fromBack {
				if err := e.sync(s, true, true); err != nil {
					return err
				}
			}
		}
		i := fileseqGalopTransStart[s]
		t := fileseqGalopTransTarget[i]
		switch fileseqGalopTransKind[i] {
		case fileseqGalopKindEpsilon:
		case fileseqGalopKindRule:
			p.stack = append(p.stack, fileseqGalopTransArg[i])
			if fileseqGalopMaxPrec > 0 {
				e.precs = append(e.precs, fileseqGalopStateCallPrec[s])
			}
		case fileseqGalopKindPrec:
			// The generated code checks precpred and fails the rule.
			if level := fileseqGalopTransArg[i]; level < e.prec() {
				return e.failedPredicate(s, level)
			}
		default:
			if fileseqGalopMatches(i, p.la(1)) {
				e.consume()
			} else if err := e.recoverInline(s, t); err != nil {
				return err
			}
			// The generated code checks for an error after a token match,
			// not after a set match.
			if fileseqGalopTransKind[i] == fileseqGalopKindAtom && e.pending != nil {
				return e.pending
			}
		}
		s = t
	}
}

// prec is the precedence of the innermost rule call, 0 in the start rule.
func (e *fileseqGalopEmu) prec() int32 {
	if len(e.precs) == 0 {
		return 0
	}
	return e.precs[len(e.precs)-1]
}

// failedPredicate is the error ANTLR reports when the precedence predicate
// of level at state s fails, in the Go target's words.
func (e *fileseqGalopEmu) failedPredicate(s int32, level int32) *fileseqGalopEmuError {
	if e.pending != nil {
		return e.pending
	}
	return &fileseqGalopEmuError{at: e.p.pos, msg: "rule " + fileseqGalopRuleName[fileseqGalopStateRule[s]] + " failed predicate: {p.Precpred(p.GetParserRuleContext(), " + fileseqGalopItoa(level) + ")}?"}
}

// fileseqGalopItoa formats n, which is not negative, in decimal; it saves both flavors
// importing strconv for one message.
func fileseqGalopItoa(n int32) string {
	if n < 10 {
		return string(rune('0' + n))
	}
	return fileseqGalopItoa(n/10) + string(rune('0'+n%10))
}

// decide makes decision d at state s as ANTLR's generated code does; fromBack
// says the walk came from the loop back of a star loop, which synced already.
func (e *fileseqGalopEmu) decide(d int, s int32, fromBack bool) (int, *fileseqGalopEmuError) {
	pos := e.p.pos
	ll1 := fileseqGalopDecisionLL1[d]
	// A token an alternative accepts passes Sync too: an LL(1) answer with no
	// error pending needs no Sync.
	if ll1 && e.pending == nil {
		if alt := e.ll1Alt(d); alt > 0 {
			return alt, nil
		}
	}
	var err *fileseqGalopEmuError
	switch fileseqGalopDecisionKind[d] {
	case fileseqGalopDecisionAlt:
		err = e.sync(s, true, true)
	case fileseqGalopDecisionOpt:
		// Adaptive prediction follows Sync with no error check.
		err = e.sync(s, true, ll1)
	case fileseqGalopDecisionStar:
		if !fromBack {
			err = e.sync(s, true, true)
		}
	case fileseqGalopDecisionPlus:
		err = e.sync(s, false, ll1)
	}
	switch {
	case err != nil:
		return 0, err
	case !ll1:
		return e.predict(d)
	}
	if alt := e.ll1Alt(d); alt > 0 {
		return alt, nil
	}
	// An LL(1) choice fails; an optional block or a loop exits.
	if fileseqGalopDecisionKind[d] == fileseqGalopDecisionAlt {
		return 0, e.noViable(pos, pos)
	}
	return int(fileseqGalopAltLookStart[d+1] - fileseqGalopAltLookStart[d]), nil
}

// predict is ANTLR's AdaptivePredict for decision d, which sets the parser's
// error to its outcome: a failure is returned, a success clears any pending
// error.
func (e *fileseqGalopEmu) predict(d int) (int, *fileseqGalopEmuError) {
	p := e.p
	pos := p.pos
	p.llBad = false
	p.prec = e.prec()
	alt, ok := func() (alt int, ok bool) {
		defer func() {
			if r := recover(); r != nil {
				if _, isSE := r.(*FileseqSyntaxError); !isSE {
					panic(r)
				}
				alt, ok = 0, false
			}
		}()
		return p.adaptivePredict(d), true
	}()
	p.pos = pos
	e.sll.note(d, pos, e.prec())
	if !ok {
		// A failed full-context stage rewinds the input before ANTLR builds
		// its error, so the error is at the decision's first token.
		if p.llBad {
			return 0, e.noViable(pos, pos)
		}
		off, fallback := e.sllFailure(d)
		if fallback == 0 {
			return 0, e.noViable(pos, off)
		}
		alt = fallback
		e.fallbacks = append(e.fallbacks, fileseqGalopFallback{int32(d), int32(pos), e.prec(), int32(alt)})
	}
	e.pending = nil
	return alt, nil
}

// fileseqGalopFlagConfig is an SLL configuration with ANTLR's reachesIntoOuterContext
// as a flag. Like ANTLR's counter, the flag belongs to the configuration, not
// to one path: configurations with the same state and alternative merge, and
// so do their flags, and what a configuration reaches inherits its flag.
type fileseqGalopFlagConfig struct {
	state, alt, ctx int32
	left            bool
}

// fileseqGalopFlagSet is a set of fileseqGalopFlagConfig, one per state and alternative. dips
// is ANTLR's dipsIntoOuterContext: building the set followed a rule's end
// with no caller known.
type fileseqGalopFlagSet struct {
	list []fileseqGalopFlagConfig
	at   fileseqGalopMap
	dips bool
}

func (s *fileseqGalopFlagSet) reset() {
	s.list = s.list[:0]
	s.at.reset()
	s.dips = false
}

func (s *fileseqGalopFlagSet) add(c fileseqGalopFlagConfig, cp *fileseqGalopCtxPool) {
	// ANTLR's Add sets dipsIntoOuterContext for any flagged configuration.
	s.dips = s.dips || c.left
	k := uint64(uint32(c.state))<<32 | uint64(uint32(c.alt))
	if i, isNew := s.at.put(k, int32(len(s.list))); !isNew {
		s.list[i].ctx = cp.merge(s.list[i].ctx, c.ctx)
		s.list[i].left = s.list[i].left || c.left
		return
	}
	s.list = append(s.list, c)
}

// key packs c as the predictor packs its configurations, with the flag in
// bit 11 of the alternative.
func (c fileseqGalopFlagConfig) key() uint64 {
	alt := c.alt
	if c.left {
		alt |= 1 << 11
	}
	return fileseqGalopConfig{c.state, alt, c.ctx}.key()
}

// fileseqGalopSLLFailure replays SLL prediction of a failed decision.
type fileseqGalopSLLFailure struct {
	pool fileseqGalopCtxPool
	busy fileseqGalopMap
	set  fileseqGalopFlagSet // the set being built
	mid  fileseqGalopFlagSet // the configurations a token reaches, before closure
	// history lists, per decision, the tokens the replay predicted it at,
	// and precs, for a decision of a left-recursive rule, the precedence of
	// each of those predictions; walked counts those whose states are built
	// already.
	history [][]int32
	precs   [][]int32
	walked  []int
	// states are the DFA states ANTLR has built, as share finds them by
	// key; starts holds each decision's start state, or -1. They and pool
	// last for the whole replay.
	states []fileseqGalopFlagState
	ids    map[string]int32
	starts []int32
	key    []byte
	// Scratch for settled.
	pr   fileseqGalopPredictor
	view []fileseqGalopConfig
	// While a start state is built (collect), prec is the precedence the
	// decision's rule invocation was called with; the precedence filter
	// state is the predictor's (see fileseqGalopPredictor).
	prec       int32
	collect    bool
	filter     bool
	rule       int32
	suppress   bool
	suppressed fileseqGalopMap
	// precStarts holds the start states of left-recursive rules' decisions,
	// by decision and precedence.
	precStarts map[int64]int32
}

// fileseqGalopFlagState is a DFA state of SLL prediction, with ANTLR's flags, and its
// edges by token type: the next state, or fileseqGalopFlagDead or fileseqGalopFlagStop.
type fileseqGalopFlagState struct {
	list  []fileseqGalopFlagConfig
	edges map[int32]int32
}

// No configuration survives the token (fileseqGalopFlagDead), or prediction stops at
// an answer (fileseqGalopFlagStop).
const (
	fileseqGalopFlagDead = int32(-1)
	fileseqGalopFlagStop = int32(-2)
)

// note records that the replay predicted decision d at token pos.
func (m *fileseqGalopSLLFailure) note(d, pos int, prec int32) {
	if m.history == nil {
		m.history = make([][]int32, len(fileseqGalopDecisionState))
		m.precs = make([][]int32, len(fileseqGalopDecisionState))
		m.walked = make([]int, len(fileseqGalopDecisionState))
		m.starts = make([]int32, len(fileseqGalopDecisionState))
		for i := range m.starts {
			m.starts[i] = -1
		}
		m.ids = map[string]int32{}
		m.pool.reset(true)
	}
	m.history[d] = append(m.history[d], int32(pos))
	if fileseqGalopDecisionPrecedence[d] {
		m.precs[d] = append(m.precs[d], prec)
	}
}

// closure is the predictor's closure with ANTLR's flags; depth is as there.
func (m *fileseqGalopSLLFailure) closure(c fileseqGalopFlagConfig, out *fileseqGalopFlagSet, depth int32) {
	if _, isNew := m.busy.put(m.busyKey(c, depth), 0); !isNew {
		return
	}
	cp := &m.pool
	s := c.state
	if fileseqGalopStateIsStop[s] {
		// In ANTLR's order (closureCheckingStopState): the empty return,
		// which sorts last, at once; the others from a stack, last first.
		// Past the rule's end with no caller known, the configuration keeps
		// its whole context, as in ANTLR.
		from, n := cp.start[c.ctx], cp.length[c.ctx]
		if n > 0 && cp.rets[from+n-1] == fileseqGalopEmptyReturn {
			m.follow(c, out, depth-1)
			n--
		}
		for i := n - 1; i >= 0; i-- {
			m.closure(fileseqGalopFlagConfig{cp.rets[from+i], c.alt, cp.parents[from+i], c.left}, out, depth-1)
		}
		return
	}
	// Within a rule the predictor's precomputed closure applies: the flag only
	// changes at a rule's end.
	for i := fileseqGalopClosStart[s]; i < fileseqGalopClosStart[s+1]; i++ {
		t := fileseqGalopClosState[i]
		switch fileseqGalopClosKind[i] {
		case 0:
			m.added(out, fileseqGalopFlagConfig{t, c.alt, c.ctx, c.left})
		case 1:
			m.closure(fileseqGalopFlagConfig{t, c.alt, cp.singleton(c.ctx, fileseqGalopClosArg[i]), c.left}, out, fileseqGalopDeeper(depth))
		case 3:
			// A precedence predicate, as in the predictor's closure.
			if !m.collect || depth != 0 || fileseqGalopClosArg[i] >= m.prec {
				m.closure(fileseqGalopFlagConfig{t, c.alt, c.ctx, c.left}, out, depth)
			}
		case 4:
			m.loopEntry(fileseqGalopFlagConfig{t, c.alt, c.ctx, c.left}, out, depth)
		default:
			m.closure(fileseqGalopFlagConfig{t, c.alt, c.ctx, c.left}, out, depth)
		}
	}
}

// loopEntry is the predictor's loopEntry with ANTLR's flags.
func (m *fileseqGalopSLLFailure) loopEntry(c fileseqGalopFlagConfig, out *fileseqGalopFlagSet, depth int32) {
	if _, isNew := m.busy.put(m.busyKey(c, depth)|1<<62, 0); !isNew {
		return
	}
	for i := fileseqGalopTransStart[c.state]; i < fileseqGalopTransStart[c.state+1]; i++ {
		if i == fileseqGalopTransStart[c.state] && m.pool.canDrop(c.state, c.ctx) {
			continue
		}
		m.closure(fileseqGalopFlagConfig{fileseqGalopTransTarget[i], c.alt, c.ctx, c.left}, out, depth)
	}
}

// busyKey and added are the predictor's, for flagged configurations.
func (m *fileseqGalopSLLFailure) busyKey(c fileseqGalopFlagConfig, depth int32) uint64 {
	key := c.key()
	if m.suppress {
		key |= 1 << 63
	}
	if m.collect && depth == 0 {
		key |= 1 << 61
	}
	return key
}

func (m *fileseqGalopSLLFailure) added(out *fileseqGalopFlagSet, c fileseqGalopFlagConfig) {
	out.add(c, &m.pool)
	if m.suppress {
		m.suppressed.put(uint64(uint32(c.state))<<32|uint64(uint32(c.alt)), 0)
	}
}

// hasEmptyPath is ANTLR's PredictionContext.hasEmptyPath: context c can end
// with nothing left on the stack.
func (m *fileseqGalopSLLFailure) hasEmptyPath(c int32) bool {
	cp := &m.pool
	n := cp.length[c]
	return n > 0 && cp.rets[cp.start[c]+n-1] == fileseqGalopEmptyReturn
}

// follow continues c, at its rule's end with no caller known, after every
// call of the rule, as SLL prediction does, flagged as having left the rule.
// A rule nobody calls keeps c there as it is.
func (m *fileseqGalopSLLFailure) follow(c fileseqGalopFlagConfig, out *fileseqGalopFlagSet, depth int32) {
	rule := fileseqGalopStateRule[c.state]
	if fileseqGalopFollowStart[rule] == fileseqGalopFollowStart[rule+1] {
		m.added(out, c)
		return
	}
	for i := fileseqGalopFollowStart[rule]; i < fileseqGalopFollowStart[rule+1]; i++ {
		f := fileseqGalopFlagConfig{fileseqGalopFollowState[i], c.alt, c.ctx, true}
		// ANTLR sets dipsIntoOuterContext here only for a configuration new
		// to the closure.
		suppress := m.filter && rule == m.rule && fileseqGalopFollowOuter[i] && !m.suppress
		if suppress {
			m.suppress = true
		}
		if _, seen := m.busy.get(m.busyKey(f, depth)); !seen {
			out.dips = true
		}
		m.closure(f, out, depth)
		if suppress {
			m.suppress = false
		}
	}
}

// sllFailure replays SLL prediction of decision d, which failed, from the
// current token. It returns the token where no configuration survives and
// the lowest alternative of a configuration flagged as having left the
// decision's rule by then, or one at a rule's end with nothing left on its
// stack (0 for none): ANTLR predicts that alternative instead of failing.
//
// The flags depend on the DFA states ANTLR already holds (see share), so the
// replay first builds the states of this parse's earlier predictions of d
// that it has not built yet, in order.
func (e *fileseqGalopEmu) sllFailure(d int) (offending int, alt int) {
	m := &e.sll
	h := m.history[d]
	for i := m.walked[d]; i < len(h)-1; i++ {
		prec := int32(0)
		if fileseqGalopDecisionPrecedence[d] {
			prec = m.precs[d][i]
		}
		m.walk(e.p.types, d, int(h[i]), prec)
	}
	m.walked[d] = len(h)
	offending, alt, _ = m.walk(e.p.types, d, e.p.pos, e.prec())
	return offending, alt
}

// walk runs SLL prediction of decision d from token from over the DFA states
// built so far, building the missing ones as ANTLR does. It reports whether
// prediction failed, and if so the token where it failed and the alternative
// ANTLR falls back on (see sllFailure).
func (m *fileseqGalopSLLFailure) walk(types []int32, d int, from int, prec int32) (offending int, alt int, failed bool) {
	st := m.start(d, prec)
	for pos := from; ; pos++ {
		t := types[pos]
		next, ok := m.states[st].edges[t]
		if !ok && t != FileseqEOF {
			next = m.target(d, st, t)
			m.states[st].edges[t] = next
		}
		// A prediction that reads EOF stops there.
		if next == fileseqGalopFlagDead || t == FileseqEOF {
			best := int32(0)
			for _, c := range m.states[st].list {
				done := fileseqGalopStateIsStop[c.state] && m.hasEmptyPath(c.ctx)
				if (c.left || done) && (best == 0 || c.alt < best) {
					best = c.alt
				}
			}
			return pos, int(best), true
		}
		if next == fileseqGalopFlagStop {
			return pos, 0, false
		}
		st = next
	}
}

// start returns decision d's start state, building it once, as ANTLR does:
// for a decision of a left-recursive rule, once per precedence its rule is
// called with.
func (m *fileseqGalopSLLFailure) start(d int, prec int32) int32 {
	key := int64(d)<<32 | int64(uint32(prec))
	if !fileseqGalopDecisionPrecedence[d] {
		if m.starts[d] >= 0 {
			return m.starts[d]
		}
	} else if st, ok := m.precStarts[key]; ok {
		return st
	}
	m.set.reset()
	m.busy.reset()
	s := fileseqGalopDecisionState[d]
	m.prec, m.collect = prec, true
	m.filter, m.rule = fileseqGalopDecisionLoopEntry[d], fileseqGalopStateRule[s]
	m.suppressed.reset()
	for i := fileseqGalopTransStart[s]; i < fileseqGalopTransStart[s+1]; i++ {
		m.closure(fileseqGalopFlagConfig{fileseqGalopTransTarget[i], i - fileseqGalopTransStart[s] + 1, 0, false}, &m.set, 0)
	}
	m.collect = false
	if m.filter {
		m.precedenceFilter(&m.set)
		m.filter = false
	}
	st := m.share(d, &m.set)
	if fileseqGalopDecisionPrecedence[d] {
		if m.precStarts == nil {
			m.precStarts = map[int64]int32{}
		}
		m.precStarts[key] = st
	} else {
		m.starts[d] = st
	}
	return st
}

// precedenceFilter is the predictor's, for flagged configurations; a
// configuration's flags do not take part.
func (m *fileseqGalopSLLFailure) precedenceFilter(set *fileseqGalopFlagSet) {
	alt1 := map[int32]int32{}
	for _, c := range set.list {
		if c.alt == 1 {
			alt1[c.state] = c.ctx
		}
	}
	n := 0
	for _, c := range set.list {
		if c.alt != 1 {
			_, spared := m.suppressed.get(uint64(uint32(c.state))<<32 | uint64(uint32(c.alt)))
			if ctx, ok := alt1[c.state]; ok && ctx == c.ctx && !spared {
				continue
			}
		}
		set.list[n] = c
		n++
	}
	set.list = set.list[:n]
	set.at.reset()
	for i, c := range set.list {
		set.at.put(uint64(uint32(c.state))<<32|uint64(uint32(c.alt)), int32(i))
	}
}

// target computes the edge of state st on token t, as ANTLR's
// computeTargetState and computeReachSet do: what t reaches is merged, then
// closed.
func (m *fileseqGalopSLLFailure) target(d int, st int32, t int32) int32 {
	m.mid.reset()
	for _, c := range m.states[st].list {
		for i := fileseqGalopTransStart[c.state]; i < fileseqGalopTransStart[c.state+1]; i++ {
			k := fileseqGalopTransKind[i]
			if (k == fileseqGalopKindAtom || k == fileseqGalopKindSet) && fileseqGalopMatches(i, t) {
				m.mid.add(fileseqGalopFlagConfig{fileseqGalopTransTarget[i], c.alt, c.ctx, c.left}, &m.pool)
			}
		}
	}
	m.set.reset()
	m.busy.reset()
	for _, c := range m.mid.list {
		m.closure(c, &m.set, 0)
	}
	switch {
	case len(m.set.list) == 0:
		return fileseqGalopFlagDead
	case m.settled(m.set.list):
		return fileseqGalopFlagStop
	}
	return m.share(d, &m.set)
}

// settled reports whether SLL prediction stops at a set, as fileseqGalopDFAGen.next does:
// one alternative is left, or an SLL conflict.
func (m *fileseqGalopSLLFailure) settled(list []fileseqGalopFlagConfig) bool {
	v := m.view[:0]
	for _, c := range list {
		v = append(v, fileseqGalopConfig{c.state, c.alt, c.ctx})
	}
	m.view = v
	return fileseqGalopUniqueAlt(v) != 0 || m.pr.conflict(v)
}

// share returns ANTLR's DFA state of decision d for set: a state built
// before for an equal set, with that state's flags, or a new state with
// set's. ANTLR's states are equal when they hold the same configurations in
// the same order (unlike fileseqGalopInternState, order counts) and agree on
// dipsIntoOuterContext; the flags do not count.
func (m *fileseqGalopSLLFailure) share(d int, set *fileseqGalopFlagSet) int32 {
	k := binary.LittleEndian.AppendUint32(m.key[:0], uint32(d))
	for _, c := range set.list {
		k = binary.LittleEndian.AppendUint32(k, uint32(c.state))
		k = binary.LittleEndian.AppendUint32(k, uint32(c.alt))
		k = binary.LittleEndian.AppendUint32(k, uint32(c.ctx))
	}
	if set.dips {
		k = append(k, 1)
	}
	m.key = k
	if id, ok := m.ids[string(k)]; ok {
		return id
	}
	id := int32(len(m.states))
	m.states = append(m.states, fileseqGalopFlagState{list: slices.Clone(set.list), edges: map[int32]int32{}})
	m.ids[string(k)] = id
	return id
}

// tokenDisplay is token i's text as ANTLR's error messages show it.
func (p *fileseqGalopParser) tokenDisplay(i int) string {
	t := p.ts.Tokens[i]
	if s := p.ts.Text(i); s != "" {
		return s
	}
	// An empty token shows its type, as ANTLR's GetTokenErrorDisplay does.
	return "<" + strconv.Itoa(int(t.Type)) + ">"
}

// inputText is the text of tokens start to stop, with the off-channel tokens
// between them, as ANTLR's token stream gives it.
func (p *fileseqGalopParser) inputText(start, stop int) string {
	var b strings.Builder
	for i := start; i <= stop; i++ {
		if i > start {
			lo, end := p.ts.hiddenRange(i)
			for h := lo; h < end; h++ {
				b.WriteString(p.ts.HiddenText(h))
			}
		}
		if p.types[i] == FileseqEOF {
			break
		}
		b.WriteString(p.ts.Text(i))
	}
	return b.String()
}

// syntaxErrorAt is a syntax error with message msg at token i.
func (p *fileseqGalopParser) syntaxErrorAt(i int, msg string) error {
	t := p.ts.Tokens[i]
	return &FileseqSyntaxError{Line: int(t.Line), Column: int(t.Column), Msg: msg}
}

